/**
 * Bible Book 49: எபேசியர் (Ephesians)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(49, {"id": 49, "testament": "NT", "code": "EPH", "name_en": "Ephesians", "name_ta": "எபேசியர்", "category": "Pauline Epistles", "category_ta": "பவுலின் நிருபங்கள்", "total_chapters": 6, "chapters": {"1": {"chapter": 1, "duration": 220.93, "audio_url": "audio_nt/B10_01.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 4.8, "end": 14.89, "ta": "தேவனுடைய சித்தத்தினாலே இயேசுகிறிஸ்துவினுடைய அப்போஸ்தலனாகிய பவுல், எபேசுவிலே கிறிஸ்து இயேசுவுக்குள் விசுவாசிகளாயிருக்கிற பரிசுத்தவான்களுக்கு எழுதுகிறதாவது:", "en": "Paul, an apostle of Jesus Christ by the will of God, to the saints which are at Ephesus, and to the faithful in Christ Jesus:"}, {"verse": 2, "start": 14.89, "end": 22.92, "ta": "நம்முடைய பிதாவாகிய தேவனாலும், கர்த்தராகிய இயேசுகிறிஸ்துவினாலும், உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக.", "en": "Grace be to you, and peace, from God our Father, and from the Lord Jesus Christ."}, {"verse": 3, "start": 22.92, "end": 34.81, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் பிதாவாகிய தேவனுக்கு ஸ்தோத்திரம்; அவர் கிறிஸ்துவுக்குள் உன்னதங்களிலே ஆவிக்குரிய சகல ஆசீர்வாதத்தினாலும் நம்மை ஆசீர்வதித்திருக்கிறார்.", "en": "Blessed be the God and Father of our Lord Jesus Christ, who hath blessed us with all spiritual blessings in heavenly places in Christ:"}, {"verse": 4, "start": 34.81, "end": 45.35, "ta": "தமக்குமுன்பாக நாம் அன்பில் பரிசுத்தமுள்ளவர்களும் குற்றமில்லாதவர்களுமாயிருப்பதற்கு, அவர் உலகத்தோற்றத்துக்கு முன்னே கிறிஸ்துவுக்குள் நம்மைத் தெரிந்துகொண்டபடியே,", "en": "According as he hath chosen us in him before the foundation of the world, that we should be holy and without blame before him in love:"}, {"verse": 5, "start": 45.35, "end": 51.13, "ta": "பிரியமானவருக்குள் தாம் நமக்குத் தந்தருளின தம்முடைய கிருபையின் மகிமைக்குப் புகழ்ச்சியாக,", "en": "Having predestinated us unto the adoption of children by Jesus Christ to himself, according to the good pleasure of his will,"}, {"verse": 6, "start": 51.13, "end": 59.68, "ta": "தம்முடைய தயவுள்ள சித்தத்தின்படியே, நம்மை இயேசுகிறிஸ்துமூலமாய்த் தமக்குச் சுவிகாரபுத்திரராகும்படி முன் குறித்திருக்கிறார்.", "en": "To the praise of the glory of his grace, wherein he hath made us accepted in the beloved."}, {"verse": 7, "start": 59.68, "end": 68.1, "ta": "அவருடைய கிருபையின் ஐசுவரியத்தின்படியே, இவருடைய இரத்தத்தினாலே பாவமன்னிப்பாகிய மீட்பு இவருக்குள் நமக்கு உண்டாயிருக்கிறது.", "en": "In whom we have redemption through his blood, the forgiveness of sins, according to the riches of his grace;"}, {"verse": 8, "start": 68.1, "end": 73.88, "ta": "அந்தக் கிருபையை அவர் சகல ஞானத்தோடும் புத்தியோடும் எங்களிடத்தில் பெருகப்பண்ணினார்.", "en": "Wherein he hath abounded toward us in all wisdom and prudence;"}, {"verse": 9, "start": 73.88, "end": 83.84, "ta": "காலங்கள் நிறைவேறும்போது விளங்கும் நியமத்தின்படி பரலோகத்திலிருக்கிறவைகளும் பூலோகத்திலிருக்கிறவைகளுமாகிய சகலமும் கிறிஸ்துவுக்குள்ளே கூட்டப்படவேண்டுமென்று,", "en": "Having made known unto us the mystery of his will, according to his good pleasure which he hath purposed in himself:"}, {"verse": 10, "start": 83.84, "end": 90.07, "ta": "தமக்குள்ளே தீர்மானித்திருந்த தம்முடைய தயவுள்ள சித்தத்தின் இரகசியத்தை எனக்கு அறிவித்தார்.", "en": "That in the dispensation of the fulness of times he might gather together in one all things in Christ, both which are in heaven, and which are on earth; even in him:"}, {"verse": 11, "start": 90.07, "end": 97.14, "ta": "மேலும் கிறிஸ்துவின்மேல் முன்னே நம்பிக்கையாயிருந்த நாங்கள் அவருடைய மகிமைக்குப் புகழ்ச்சியாயிருக்கும்படிக்கு,", "en": "In whom also we have obtained an inheritance, being predestinated according to the purpose of him who worketh all things after the counsel of his own will:"}, {"verse": 12, "start": 97.14, "end": 109.99, "ta": "தமது சித்தத்தின் ஆலோசனைக்குத்தக்கதாக எல்லாவற்றையும் நடப்பிக்கிற அவருடைய தீர்மானத்தின்படியே, நாங்கள் முன்குறிக்கப்பட்டு, கிறிஸ்துவுக்குள் அவருடைய சுதந்தரமாகும்படி தெரிந்துகொள்ளப்பட்டோம்.", "en": "That we should be to the praise of his glory, who first trusted in Christ."}, {"verse": 13, "start": 109.99, "end": 121.43, "ta": "நீங்களும் உங்கள் இரட்சிப்பின் சுவிசேஷமாகிய சத்திய வசனத்தைக் கேட்டு, விசுவாசிகளானபோது, வாக்குத்தத்தம்பண்ணப்பட்ட பரிசுத்த ஆவியால் அவருக்குள் முத்திரைபோடப்பட்டீர்கள்.", "en": "In whom ye also trusted , after that ye heard the word of truth, the gospel of your salvation: in whom also after that ye believed, ye were sealed with that holy Spirit of promise,"}, {"verse": 14, "start": 121.43, "end": 131.07, "ta": "அவருக்குச் சொந்தமானவர்கள் அவருடைய மகிமைக்குப் புகழ்ச்சியாக மீட்கப்படுவார்கள் என்பதற்கு ஆவியானவர் நம்முடைய சுதந்தரத்தின் அச்சாரமாயிருக்கிறார்.", "en": "Which is the earnest of our inheritance until the redemption of the purchased possession, unto the praise of his glory."}, {"verse": 15, "start": 131.07, "end": 140.58, "ta": "ஆனபடியினாலே, கர்த்தராகிய இயேசுவின்மேலுள்ள உங்கள் விசுவாசத்தையும், பரிசுத்தவான்களெல்லார்மேலுள்ள உங்கள் அன்பையுங்குறித்து நான் கேள்விப்பட்டு,", "en": "Wherefore I also, after I heard of your faith in the Lord Jesus, and love unto all the saints,"}, {"verse": 16, "start": 140.58, "end": 145.59, "ta": "இடைவிடாமல் உங்களுக்காக ஸ்தோத்திரம்பண்ணி, என் ஜெபங்களில் உங்களை நினைத்து,", "en": "Cease not to give thanks for you, making mention of you in my prayers;"}, {"verse": 17, "start": 145.59, "end": 157.1, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் தேவனும் மகிமையின் பிதாவுமானவர் தம்மை நீங்கள் அறிந்துகொள்வதற்கான ஞானத்தையும் தெளிவையும் அளிக்கிற ஆவியை உங்களுக்குத் தந்தருளவேண்டுமென்றும்,", "en": "That the God of our Lord Jesus Christ, the Father of glory, may give unto you the spirit of wisdom and revelation in the knowledge of him:"}, {"verse": 18, "start": 157.1, "end": 168.28, "ta": "தாம் நம்மை அழைத்ததினாலே நமக்கு உண்டாயிருக்கிற நம்பிக்கை இன்னதென்றும், பரிசுத்தவான்களிடத்தில் தமக்கு உண்டாயிருக்கிற சுதந்தரத்தினுடைய மகிமையின் ஐசுவரியம் இன்னதென்றும்;", "en": "The eyes of your understanding being enlightened; that ye may know what is the hope of his calling, and what the riches of the glory of his inheritance in the saints,"}, {"verse": 19, "start": 168.28, "end": 190.0, "ta": "தாம் கிறிஸ்துவை மரித்தோரிலிருந்து எழுப்பி, அவரிடத்தில் நடப்பித்த தமது பலத்த சத்துவத்தின் வல்லமைப்படியே விசுவாசிக்கிறவர்களாகிய நம்மிடத்திலே காண்பிக்கும் தம்முடைய வல்லமையின் மகா மேன்மையான மகத்துவம் இன்னதென்றும், நீங்கள் அறியும்படிக்கு, அவர் உங்களுக்குப் பிரகாசமுள்ள மனக்கண்களைக் கொடுக்கவேண்டுமென்றும் வேண்டிக்கொள்ளுகிறேன்.", "en": "And what is the exceeding greatness of his power to us-ward who believe, according to the working of his mighty power,"}, {"verse": 20, "start": 190.0, "end": 203.17, "ta": "எல்லாத் துரைத்தனத்துக்கும், அதிகாரத்துக்கும், வல்லமைக்கும், கர்த்தத்துவத்துக்கும், இம்மையில்மாத்திரமல்ல மறுமையிலும் பேர்பெற்றிருக்கும் எல்லா நாமத்துக்கும் மேலாய் அவர் உயர்ந்திருக்கத்தக்கதாக,", "en": "Which he wrought in Christ, when he raised him from the dead, and set him at his own right hand in the heavenly places ,"}, {"verse": 21, "start": 203.17, "end": 207.41, "ta": "அவரை உன்னதங்களில் தம்முடைய வலதுபாரிசத்தில் உட்காரும்படி செய்து,", "en": "Far above all principality, and power, and might, and dominion, and every name that is named, not only in this world, but also in that which is to come:"}, {"verse": 22, "start": 207.41, "end": 210.95, "ta": "எல்லாவற்றையும் அவருடைய பாதங்களுக்குக் கீழ்ப்படுத்தி,", "en": "And hath put all things under his feet, and gave him to be the head over all things to the church,"}, {"verse": 23, "start": 210.95, "end": 219.43, "ta": "எல்லாவற்றையும் எல்லாவற்றாலும் நிரப்புகிறவருடைய நிறைவாகிய சரீரமான சபைக்கு அவரை எல்லாவற்றிற்கும் மேலான தலையாகத் தந்தருளினார்.", "en": "Which is his body, the fulness of him that filleth all in all."}]}, "2": {"chapter": 2, "duration": 202.46, "audio_url": "audio_nt/B10_02.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 9.43, "ta": "அக்கிரமங்களினாலும் பாவங்களினாலும் மரித்தவர்களாயிருந்த உங்களை உயிர்ப்பித்தார்.", "en": "And you hath he quickened , who were dead in trespasses and sins;"}, {"verse": 2, "start": 9.43, "end": 22.91, "ta": "அவைகளில் நீங்கள் முற்காலத்திலே இவ்வுலக வழக்கத்திற்கேற்றபடியாகவும், கீழ்ப்படியாமையின் பிள்ளைகளிடத்தில் இப்பொழுது கிரியைசெய்கிற ஆகாயத்து அதிகாரப் பிரபுவாகிய ஆவிக்கேற்றபடியாகவும் நடந்துகொண்டீர்கள்.", "en": "Wherein in time past ye walked according to the course of this world, according to the prince of the power of the air, the spirit that now worketh in the children of disobedience:"}, {"verse": 3, "start": 22.91, "end": 36.33, "ta": "அவர்களுக்குள்ளே நாமெல்லாரும் முற்காலத்திலே நமது மாம்ச இச்சையின்டியே நடந்து, நமது மாம்சமும் மனசும் விரும்பினவைகளைச் செய்து, சுபாவத்தினாலே மற்றவர்களைப்போலக் கோபாக்கினையின் பிள்ளைகளாயிருந்தோம்.", "en": "Among whom also we all had our conversation in times past in the lusts of our flesh, fulfilling the desires of the flesh and of the mind; and were by nature the children of wrath, even as others."}, {"verse": 4, "start": 36.33, "end": 42.03, "ta": "தேவனோ இரக்கத்தில் ஐசுவரியமுள்ளவராய் நம்மில் அன்புகூர்ந்த தம்முடைய மிகுந்த அன்பினாலே,", "en": "But God, who is rich in mercy, for his great love wherewith he loved us,"}, {"verse": 5, "start": 42.03, "end": 50.34, "ta": "அக்கிரமங்களில் மரித்தவர்களாயிருந்த நம்மைக் கிறிஸ்துவுடனேகூட உயிர்ப்பித்தார்; கிருபையினாலே இரட்சிக்கப்பட்டீர்கள்.", "en": "Even when we were dead in sins, hath quickened us together with Christ, (by grace ye are saved;)"}, {"verse": 6, "start": 50.34, "end": 59.83, "ta": "கிறிஸ்து இயேசுவுக்குள் அவர் நம்மிடத்தில் வைத்த தயவினாலே, தம்முடைய கிருபையின் மகா மேன்மையான ஐசுவரியத்தை வருங்காலங்களில் விளங்கச்செய்வதற்காக,", "en": "And hath raised us up together, and made us sit together in heavenly places in Christ Jesus:"}, {"verse": 7, "start": 59.83, "end": 66.57, "ta": "கிறிஸ்து இயேசுவுக்குள் நம்மை அவரோடேகூட எழுப்பி, உன்னதங்களிலே அவரோடேகூட உட்காரவும் செய்தார்.", "en": "That in the ages to come he might shew the exceeding riches of his grace in his kindness toward us through Christ Jesus."}, {"verse": 8, "start": 66.57, "end": 73.97, "ta": "கிருபையினாலே விசுவாசத்தைக்கொண்டு இரட்சிக்கப்பட்டீர்கள்; இது உங்களால் உண்டானதல்ல, இது தேவனுடைய ஈவு;", "en": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"}, {"verse": 9, "start": 73.97, "end": 78.36, "ta": "ஒருவரும் பெருமைபாராட்டாதபடிக்கு இது கிரியைகளினால் உண்டானதல்ல;", "en": "Not of works, lest any man should boast."}, {"verse": 10, "start": 78.36, "end": 92.04, "ta": "ஏனெனில், நற்கிரியைகளைச் செய்கிறதற்கு நாம் கிறிஸ்து இயேசுவுக்குள் சிருஷ்டிக்கப்பட்டு, தேவனுடைய செய்கையாயிருக்கிறோம்; அவைகளில் நாம் நடக்கும்படி அவர் முன்னதாக அவைகளை ஆயத்தம்பண்ணியிருக்கிறார்.", "en": "For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them."}, {"verse": 11, "start": 92.04, "end": 102.71, "ta": "ஆனபடியினால் முன்னே மாம்சத்தின்படி புறஜாதியாராயிருந்து, மாம்சத்தில் கையினாலே செய்யப்படுகிற விருத்தசேதனமுடையவர்களால் விருத்தசேதனமில்லாதவர்களென்னப்பட்ட நீங்கள்,", "en": "Wherefore remember, that ye being in time past Gentiles in the flesh, who are called Uncircumcision by that which is called the Circumcision in the flesh made by hands;"}, {"verse": 12, "start": 102.71, "end": 119.66, "ta": "அக்காலத்திலே இயேசுகிறிஸ்துவைச் சேராதவர்களும், இஸ்ரவேலுடைய காணியாட்சிக்குப் புறம்பானவர்களும், வாக்குத்தத்தத்தின் உடன்படிக்கைகளுக்கு அந்நியரும், நம்பிக்கையில்லாதவர்களும், இவ்வுலகத்தில் தேவனற்றவர்களுமாயிருந்தீர்களென்று நினைத்துக்கொள்ளுங்கள்.", "en": "That at that time ye were without Christ, being aliens from the commonwealth of Israel, and strangers from the covenants of promise, having no hope, and without God in the world:"}, {"verse": 13, "start": 119.66, "end": 126.93, "ta": "முன்னே தூரமாயிருந்த நீங்கள் இப்பொழுது கிறிஸ்து இயேசுவுக்குள் கிறிஸ்துவின் இரத்தத்தினாலே சமீபமானீர்கள்.", "en": "But now in Christ Jesus ye who sometimes were far off are made nigh by the blood of Christ."}, {"verse": 14, "start": 126.93, "end": 135.57, "ta": "எப்படியெனில், அவரே நம்முடைய சமாதானகாரராகி, இருதிறத்தாரையும் ஒன்றாக்கி, பகையாக நின்ற பிரிவினையாகிய நடுச்சுவரைத் தகர்த்து,", "en": "For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us ;"}, {"verse": 15, "start": 135.57, "end": 146.37, "ta": "சட்டதிட்டங்களாகிய நியாயப்பிரமாணத்தைத் தம்முடைய மாம்சத்தினாலே ஒழித்து, இருதிறத்தாரையும் தமக்குள்ளாக ஒரே புதிய மனுஷனாகச் சிருஷ்டித்து, இப்படிச் சமாதானம்பண்ணி,", "en": "Having abolished in his flesh the enmity, even the law of commandments contained in ordinances; for to make in himself of twain one new man, so making peace;"}, {"verse": 16, "start": 146.37, "end": 153.24, "ta": "பகையைச் சிலுவையினால் கொன்று, அதினாலே இருதிறத்தாரையும் ஒரே சரீரமாக தேவனுக்கு ஒப்புரவாக்கினார்.", "en": "And that he might reconcile both unto God in one body by the cross, having slain the enmity thereby:"}, {"verse": 17, "start": 153.24, "end": 161.95, "ta": "அல்லாமலும் அவர் வந்து, தூரமாயிருந்த உங்களுக்கும், சமீபமாயிருந்த அவர்களுக்கும், சமாதானத்தைச் சுவிசேஷமாக அறிவித்தார்.", "en": "And came and preached peace to you which were afar off, and to them that were nigh."}, {"verse": 18, "start": 161.95, "end": 170.0, "ta": "அந்தப்படியே நாம் இருதிறத்தாரும் ஒரே ஆவியினாலே பிதாவினிடத்தில் சேரும் சிலாக்கியத்தை அவர்மூலமாய்ப் பெற்றிருக்கிறோம்.", "en": "For through him we both have access by one Spirit unto the Father."}, {"verse": 19, "start": 170.0, "end": 178.05, "ta": "ஆகையால், நீங்கள் இனி அந்நியரும் பரதேசிகளுமாயிராமல், பரிசுத்தவான்களோடே ஒரே நகரத்தாரும் தேவனுடைய வீட்டாருமாயிருந்து,", "en": "Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;"}, {"verse": 20, "start": 178.05, "end": 188.26, "ta": "அப்போஸ்தலர் தீர்க்கதரிசிகளென்பவர்களுடைய அஸ்திபாரத்தின்மேல் கட்டப்பட்டவர்களுமாயிருக்கிறீர்கள்; அதற்கு இயேசுகிறிஸ்து தாமே மூலைக்கல்லாயிருக்கிறார்;", "en": "And are built upon the foundation of the apostles and prophets, Jesus Christ himself being the chief corner stone ;"}, {"verse": 21, "start": 188.26, "end": 194.94, "ta": "அவர்மேல் மாளிகை முழுவதும் இசைவாய் இணைக்கப்பட்டு, கர்த்தருக்குள் பரிசுத்த ஆலயமாக எழும்புகிறது;", "en": "In whom all the building fitly framed together groweth unto an holy temple in the Lord:"}, {"verse": 22, "start": 194.94, "end": 200.96, "ta": "அவர்மேல் நீங்களும் ஆவியினாலே தேவனுடைய வாசஸ்தலமாகக் கூட்டிக்கட்டப்பட்டுவருகிறீர்கள்.", "en": "In whom ye also are builded together for an habitation of God through the Spirit."}]}, "3": {"chapter": 3, "duration": 196.95, "audio_url": "audio_nt/B10_03.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 12.24, "ta": "இதினித்தம், பவுலாகிய நான் புறஜாதியாராயிருக்கிற உங்கள்பொருட்டுக் கிறிஸ்து இயேசுவினிமித்தம் கட்டுண்டவனாயிருக்கிறேன்.", "en": "For this cause I Paul, the prisoner of Jesus Christ for you Gentiles,"}, {"verse": 2, "start": 12.24, "end": 19.01, "ta": "உங்களுக்காக எனக்கு அளிக்கப்பட்டிருக்கிற தெய்வகிருபைக்குரிய நியமமுமின்னதென்று கேட்டிருப்பீர்களே;", "en": "If ye have heard of the dispensation of the grace of God which is given me to you-ward:"}, {"verse": 3, "start": 19.01, "end": 35.7, "ta": "அதென்னவெனில் புறஜாதிகள் சுவிசேஷத்தினாலே உடன் சுதந்தரருமாய், ஒரே சரீரத்திற்குள்ளானவர்களுமாய், கிறிஸ்துவுக்குள் அவர் பண்ணின வாக்குத்தத்தத்துக்கு உடன்பங்காளிகளுமாயிருக்கிறார்களென்கிற இந்த இரகசியத்தை அவர் எனக்கு வெளிப்படுத்தி அறிவித்தார்.", "en": "How that by revelation he made known unto me the mystery; (as I wrote afore in few words,"}, {"verse": 4, "start": 35.7, "end": 40.12, "ta": "இதைக்குறித்து நான் முன்னமே சுருக்கமாய் எழுதியிருக்கிறேன்.", "en": "Whereby, when ye read, ye may understand my knowledge in the mystery of Christ)"}, {"verse": 5, "start": 40.12, "end": 47.49, "ta": "அதை நீங்கள் வாசிக்கையில் கிறிஸ்துவின் இரகசியத்தைக்குறித்து எனக்கு உண்டாயிருக்கிற அறிவை அறிந்துகொள்ளலாம்;", "en": "Which in other ages was not made known unto the sons of men, as it is now revealed unto his holy apostles and prophets by the Spirit;"}, {"verse": 6, "start": 47.49, "end": 60.16, "ta": "இந்த இரகசியம் இப்பொழுது அவருடைய பரிசுத்த அப்போஸ்தலருக்கும் தீர்க்கதரிசிகளுக்கும் ஆவியானவராலே வெளிப்படுத்தப்பட்டிருக்கிறதுபோல, முற்காலங்களில் மனுபுத்திரருக்கு அறிவிக்கப்படவில்லை.", "en": "That the Gentiles should be fellowheirs, and of the same body, and partakers of his promise in Christ by the gospel:"}, {"verse": 7, "start": 60.16, "end": 68.53, "ta": "தேவனுடைய பலத்த சத்துவத்தால் எனக்கு அளிக்கப்பட்ட வரமாகிய அவருடைய கிருபையினாலே இந்தச் சுவிசேஷத்துக்கு ஊழியக்காரனானேன்.", "en": "Whereof I was made a minister, according to the gift of the grace of God given unto me by the effectual working of his power."}, {"verse": 8, "start": 68.53, "end": 80.59, "ta": "பரிசுத்தவான்களெல்லாரிலும் சிறியவனாகிய நான் கிறிஸ்துவினுடைய அளவற்ற ஐசுவரியத்தைப் புறஜாதிகளிடத்தில் சுவிசேஷமாய் அறிவிக்கிறதற்காக இந்தக் கிருபை எனக்கு அளிக்கப்பட்டிருக்கிறது.", "en": "Unto me, who am less than the least of all saints, is this grace given, that I should preach among the Gentiles the unsearchable riches of Christ;"}, {"verse": 9, "start": 80.59, "end": 86.62, "ta": "தேவன் நம்முடைய கர்த்தராகிய கிறிஸ்து இயேசுவுக்குள் கொண்டிருந்த அநாதி தீர்மானத்தின்படியே,", "en": "And to make all men see what is the fellowship of the mystery, which from the beginning of the world hath been hid in God, who created all things by Jesus Christ:"}, {"verse": 10, "start": 86.62, "end": 95.0, "ta": "உன்னதங்களிலுள்ள துரைத்தனங்களுக்கும் அதிகாரங்களுக்கும் அவருடைய அநந்த ஞானமானது சபையின்மூலமாய் இப்பொழுது தெரியவரும்பொருட்டாக,", "en": "To the intent that now unto the principalities and powers in heavenly places might be known by the church the manifold wisdom of God,"}, {"verse": 11, "start": 95.0, "end": 110.95, "ta": "இயேசுகிறிஸ்துவைக்கொண்டு எல்லாவற்றையும் சிருஷ்டித்த தேவனுக்குள்ளே ஆதிகாலங்கள் முதல் மறைந்திருந்த இரகசியத்தினுடைய ஐக்கியம் இன்னதென்று, எல்லாருக்கும் வெளிப்படையாகக் காண்பிக்கிறதற்கு, இந்தக்கிருபை எனக்கு அளிக்கப்பட்டிருக்கிறது.", "en": "According to the eternal purpose which he purposed in Christ Jesus our Lord:"}, {"verse": 12, "start": 110.95, "end": 120.0, "ta": "அவரைப் பற்றும் விசுவாசத்தால் அவருக்குள் நமக்குத் தைரியமும் திடநம்பிக்கையோடே அவரிடத்தில் சேரும் சிலாக்கியமும் உண்டாயிருக்கிறது.", "en": "In whom we have boldness and access with confidence by the faith of him."}, {"verse": 13, "start": 120.0, "end": 130.78, "ta": "ஆகையால் உங்கள்நிமித்தம் நான் அநுபவிக்கிற உபத்திரவங்களினால் நீங்கள் சோர்ந்துபோகாதிருக்க வேண்டிக்கொள்ளுகிறேன்; அவைகள் உங்களுக்கு மகிமையாயிருக்கிறதே.", "en": "Wherefore I desire that ye faint not at my tribulations for you, which is your glory."}, {"verse": 14, "start": 130.78, "end": 136.75, "ta": "இதினிமித்தம் நான் பரலோகத்திலும் பூலோகத்திலுமுள்ள முழுக்குடும்பத்துக்கும் நாமகாரணராகிய,", "en": "For this cause I bow my knees unto the Father of our Lord Jesus Christ,"}, {"verse": 15, "start": 136.75, "end": 142.38, "ta": "நம்முடைய கர்த்தராயிருக்கிற இயேசுகிறிஸ்துவினுடைய பிதாவை நோக்கி முழங்கால்படியிட்டு,", "en": "Of whom the whole family in heaven and earth is named,"}, {"verse": 16, "start": 142.38, "end": 147.0, "ta": "நீங்கள் அவருடைய ஆவியினாலே உள்ளான மனுஷனில் வல்லமையாய்ப் பலப்படவும்,", "en": "That he would grant you, according to the riches of his glory, to be strengthened with might by his Spirit in the inner man;"}, {"verse": 17, "start": 147.0, "end": 154.77, "ta": "விசுவாசத்தினாலே கிறிஸ்து உங்கள் இருதயங்களில் வாசமாயிருக்கவும், நீங்கள் அன்பிலே வேரூன்றி, நிலைபெற்றவர்களாகி,", "en": "That Christ may dwell in your hearts by faith; that ye, being rooted and grounded in love,"}, {"verse": 18, "start": 154.77, "end": 162.95, "ta": "சகல பரிசுத்தவான்களோடுங்கூடக் கிறிஸ்துவினுடைய அன்பின் அகலமும், நீளமும், ஆழமும், உயரமும் இன்னதென்று உணர்ந்து;", "en": "May be able to comprehend with all saints what is the breadth, and length, and depth, and height;"}, {"verse": 19, "start": 162.95, "end": 177.83, "ta": "அறிவுக்கெட்டாத அந்த அன்பை அறிந்துகொள்ள வல்லவர்களாகவும், தேவனுடைய சகல பரிபூரணத்தாலும் நிறையப்படவும், அவர் தமது மகிமையினுடைய ஐசுவரியத்தின்படியே, உங்களுக்கு அநுக்கிரகம் பண்ணவேண்டுமென்று வேண்டிக்கொள்ளுகிறேன்.", "en": "And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God."}, {"verse": 20, "start": 177.83, "end": 187.68, "ta": "நாம் வேண்டிக்கொள்ளுகிறதற்கும் நினைக்கிறதற்கும் மிகவும் அதிகமாய் நமக்குள்ளே கிரியைசெய்கிற வல்லமையின்படியே, நமக்குச் செய்ய வல்லவராகிய அவருக்கு,", "en": "Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,"}, {"verse": 21, "start": 187.68, "end": 195.45, "ta": "சபையிலே கிறிஸ்து இயேசுவின் மூலமாய்த் தலைமுறை தலைமுறைக்கும் சதாகாலங்களிலும் மகிமை உண்டாவதாக. ஆமென்.", "en": "Unto him be glory in the church by Christ Jesus throughout all ages, world without end. Amen."}]}, "4": {"chapter": 4, "duration": 260.35, "audio_url": "audio_nt/B10_04.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 13.46, "ta": "ஆதலால், கர்த்தர்நிமித்தம் கட்டுண்டவனாகிய நான் உங்களுக்குச் சொல்லுகிற புத்தியென்னவெனில், நீங்கள் அழைக்கப்பட்ட அழைப்புக்குப் பாத்திரவான்களாய் நடந்து,", "en": "I therefore, the prisoner of the Lord, beseech you that ye walk worthy of the vocation wherewith ye are called,"}, {"verse": 2, "start": 13.46, "end": 19.72, "ta": "மிகுந்த மனத்தாழ்மையும் சாந்தமும் நீடிய பொறுமையும் உடையவர்களாய், அன்பினால் ஒருவரையொருவர் தாங்கி,", "en": "With all lowliness and meekness, with longsuffering, forbearing one another in love;"}, {"verse": 3, "start": 19.72, "end": 24.99, "ta": "சமாதானக்கட்டினால் ஆவியின் ஒருமையைக் காத்துக்கொள்வதற்கு ஜாக்கிரதையாயிருங்கள்.", "en": "Endeavouring to keep the unity of the Spirit in the bond of peace."}, {"verse": 4, "start": 24.99, "end": 32.11, "ta": "உங்களுக்கு உண்டான அழைப்பினாலே நீங்கள் ஒரே நம்பிக்கைக்கு அழைக்கப்பட்டதுபோல, ஒரே சரீரமும் ஒரே ஆவியும் உண்டு;", "en": "There is one body, and one Spirit, even as ye are called in one hope of your calling;"}, {"verse": 5, "start": 32.11, "end": 35.77, "ta": "ஒரே கர்த்தரும், ஒரே விசுவாசமும், ஒரே ஞானஸ்நானமும்,", "en": "One Lord, one faith, one baptism,"}, {"verse": 6, "start": 35.77, "end": 44.01, "ta": "எல்லாருக்கும் ஒரே தேவனும் பிதாவும் உண்டு; அவர் எல்லார்மேலும், எல்லாரோடும், உங்கள் எல்லாருக்குள்ளும் இருக்கிறவர்.", "en": "One God and Father of all, who is above all, and through all, and in you all."}, {"verse": 7, "start": 44.01, "end": 50.2, "ta": "கிறிஸ்துவினுடைய ஈவின் அளவுக்குத்தக்கதாக நம்மில் அவனவனுக்குக் கிருபை அளிக்கப்பட்டிருக்கிறது.", "en": "But unto every one of us is given grace according to the measure of the gift of Christ."}, {"verse": 8, "start": 50.2, "end": 58.75, "ta": "ஆதலால், அவர் உன்னதத்திற்கு ஏறி, சிறைப்பட்டவர்களைச் சிறையாக்கி, மனுஷர்களுக்கு வரங்களை அளித்தார் என்று சொல்லியிருக்கிறார்.", "en": "Wherefore he saith, When he ascended up on high, he led captivity captive, and gave gifts unto men."}, {"verse": 9, "start": 58.75, "end": 65.19, "ta": "ஏறினார் என்பதினாலே அவர் அதற்குமுன்னே பூமியின் தாழ்விடங்களில் இறங்கினார் என்று விளங்குகிறதல்லவா?", "en": "(Now that he ascended, what is it but that he also descended first into the lower parts of the earth?"}, {"verse": 10, "start": 65.19, "end": 72.5, "ta": "இறங்கினவரே எல்லாவற்றையும் நிரப்பத்தக்கதாக, எல்லா வானங்களுக்கும் மேலாக உன்னதத்திற்கு ஏறினவருமாயிருக்கிறார்.", "en": "He that descended is the same also that ascended up far above all heavens, that he might fill all things.)"}, {"verse": 11, "start": 72.5, "end": 83.59, "ta": "மேலும் நாம் அனைவரும் தேவனுடைய குமாரனைப் பற்றும் விசுவாசத்திலும் அறிவிலும் ஒருமைப்பட்டவர்களாகி, கிறிஸ்துவினுடைய நிறைவான வளர்ச்சியின் அளவுக்குத்தக்க பூரண புருஷராகும்வரைக்கும்,", "en": "And he gave some, apostles; and some, prophets; and some, evangelists; and some, pastors and teachers;"}, {"verse": 12, "start": 83.59, "end": 92.51, "ta": "பரிசுத்தவான்கள் சீர்பொருந்தும்பொருட்டு, சுவிசேஷ ஊழியத்தின் வேலைக்காகவும், கிறிஸ்துவின் சரீரமாகிய சபையானது பக்திவிருத்தி அடைவதற்காகவும்,", "en": "For the perfecting of the saints, for the work of the ministry, for the edifying of the body of Christ:"}, {"verse": 13, "start": 92.51, "end": 102.3, "ta": "அவர், சிலரை அப்போஸ்தலராகவும், சிலரைத் தீர்க்கதரிசிகளாகவும், சிலரைச் சுவிசேஷகராகவும், சிலரை மேய்ப்பராகவும், போதகராகவும் ஏற்படுத்தினார்.", "en": "Till we all come in the unity of the faith, and of the knowledge of the Son of God, unto a perfect man, unto the measure of the stature of the fulness of Christ:"}, {"verse": 14, "start": 102.3, "end": 111.9, "ta": "நாம் இனிக் குழந்தைகளாயிராமல், மனுஷருடைய சூதும் வஞ்சிக்கிறதற்கேதுவான தந்திரமுமுள்ள போதகமாய் பலவித காற்றினாலே அலைகளைப்போல அடிபட்டு அலைகிறவர்களாயிராமல்,", "en": "That we henceforth be no more children, tossed to and fro, and carried about with every wind of doctrine, by the sleight of men, and cunning craftiness, whereby they lie in wait to deceive;"}, {"verse": 15, "start": 111.9, "end": 120.58, "ta": "அன்புடன் சத்தியத்தைக் கைகொண்டு தலையாகிய கிறிஸ்துவுக்குள் எல்லாவற்றிலேயும், நாம் வளருகிறவர்களாயிருக்கும்படியாக அப்படிச் செய்தார்.", "en": "But speaking the truth in love, may grow up into him in all things, which is the head, even Christ:"}, {"verse": 16, "start": 120.58, "end": 137.3, "ta": "அவராலே சரீரம் முழுதும், அதற்கு உதவியாயிருக்கிற சகல கணுக்களினாலும் இசைவாய்க் கட்டி இணைக்கப்பட்டு, ஒவ்வொரு அவயவமும் தன்தன் அளவுக்குத்தக்கதாய்க் கிரியைசெய்கிறபடியே, அது அன்பினாலே தனக்கு பக்திவிருத்தி உண்டாக்குகிறதற்கேதுவாகச் சரீரவளர்ச்சியை உண்டாக்குகிறது.", "en": "From whom the whole body fitly joined together and compacted by that which every joint supplieth, according to the effectual working in the measure of every part, maketh increase of the body unto the edifying of itself in love."}, {"verse": 17, "start": 137.3, "end": 148.64, "ta": "ஆதலால், கர்த்தருக்குள் நான் உங்களுக்குச் சாட்சியாகச் சொல்லி எச்சரிக்கிறது என்னவெனில், மற்றப் புறஜாதிகள் தங்கள் வீணான சிந்தையிலே நடக்கிறதுபோல நீங்கள் இனி நடவாமலிருங்கள்.", "en": "This I say therefore, and testify in the Lord, that ye henceforth walk not as other Gentiles walk, in the vanity of their mind,"}, {"verse": 18, "start": 148.64, "end": 157.25, "ta": "அவர்கள் புத்தியில் அந்தகாரப்பட்டு, தங்கள் இருதய கடினத்தினால் தங்களில் இருக்கும் அறியாமையினாலே தேவனுடைய ஜீவனுக்கு அந்நியராயிருந்து;", "en": "Having the understanding darkened, being alienated from the life of God through the ignorance that is in them, because of the blindness of their heart:"}, {"verse": 19, "start": 157.25, "end": 165.8, "ta": "உணர்வில்லாதவர்களாய், சகலவித அசுத்தங்களையும் ஆவலோடே நடப்பிக்கும்படி, தங்களைக் காமவிகாரத்திற்கு ஒப்புக்கொடுத்திருக்கிறார்கள்.", "en": "Who being past feeling have given themselves over unto lasciviousness, to work all uncleanness with greediness."}, {"verse": 20, "start": 165.8, "end": 169.64, "ta": "நீங்களோ இவ்விதமாய்க் கிறிஸ்துவைக் கற்றுக்கொள்ளவில்லை.", "en": "But ye have not so learned Christ;"}, {"verse": 21, "start": 169.64, "end": 176.7, "ta": "இயேசுவினிடத்திலுள்ள சத்தியத்தின்படியே, நீங்கள் அவரிடத்தில் கேட்டறிந்து, அவரால் போதிக்கப்பட்டீர்களே.", "en": "If so be that ye have heard him, and have been taught by him, as the truth is in Jesus:"}, {"verse": 22, "start": 176.7, "end": 183.64, "ta": "அந்தப்படி, முந்தின நடக்கைக்குரிய மோசம்போக்கும் இச்சைகளாலே கெட்டுப்போகிற பழைய மனுஷனை நீங்கள் களைந்துபோட்டு,", "en": "That ye put off concerning the former conversation the old man, which is corrupt according to the deceitful lusts;"}, {"verse": 23, "start": 183.64, "end": 186.49, "ta": "உங்கள் உள்ளத்திலே புதிதான ஆவியுள்ளவர்களாகி,", "en": "And be renewed in the spirit of your mind;"}, {"verse": 24, "start": 186.49, "end": 193.62, "ta": "மெய்யான நீதியிலும் பரிசுத்தத்திலும் தேவனுடைய சாயலாக சிருஷ்டிக்கப்பட்ட புதிய மனுஷனைத் தரித்துக்கொள்ளுங்கள்.", "en": "And that ye put on the new man, which after God is created in righteousness and true holiness."}, {"verse": 25, "start": 193.62, "end": 201.73, "ta": "அன்றியும், நாம் ஒருவருக்கொருவர் அவயவங்களாயிருக்கிறபடியால், பொய்யைக் களைந்து, அவனவன் பிறனுடனே மெய்யைப் பேசக்கடவன்.", "en": "Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another."}, {"verse": 26, "start": 201.73, "end": 208.92, "ta": "நீங்கள் கோபங்கொண்டாலும் பாவஞ்செய்யாதிருங்கள், சூரியன் அஸ்தமிக்கிறதற்கு முன்னாக உங்கள் எரிச்சல் தணியக்கடவது;", "en": "Be ye angry, and sin not: let not the sun go down upon your wrath:"}, {"verse": 27, "start": 208.92, "end": 211.58, "ta": "பிசாசுக்கு இடங்கொடாமலும் இருங்கள்.", "en": "Neither give place to the devil."}, {"verse": 28, "start": 211.58, "end": 221.87, "ta": "திருடுகிறவன் இனித் திருடாமல், குறைச்சலுள்ளவனுக்குக் கொடுக்கத்தக்கதாகத் தனக்கு உண்டாயிருக்கும்படி, தன் கைகளினால் நலமான வேலைசெய்து, பிரயாசப்படக்கடவன்.", "en": "Let him that stole steal no more: but rather let him labour, working with his hands the thing which is good, that he may have to give to him that needeth."}, {"verse": 29, "start": 221.87, "end": 232.89, "ta": "கெட்ட வார்த்தை ஒன்றும் உங்கள் வாயிலிருந்து புறப்படவேண்டாம்; பக்திவிருத்திக்கு ஏதுவான நல்ல வார்த்தை உண்டானால் அதையே கேட்கிறவனுக்குப் பிரயோஜனமுண்டாகும்படி பேசுங்கள்.", "en": "Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers."}, {"verse": 30, "start": 232.89, "end": 240.7, "ta": "அன்றியும், நீங்கள் மீட்கப்படும்நாளுக்கென்று முத்திரையாகப் பெற்ற தேவனுடைய பரிசுத்த ஆவியைத் துக்கப்படுத்தாதிருங்கள்.", "en": "And grieve not the holy Spirit of God, whereby ye are sealed unto the day of redemption."}, {"verse": 31, "start": 240.7, "end": 249.43, "ta": "சகலவிதமான கசப்பும், கோபமும், மூர்க்கமும், கூக்குரலும், தூஷணமும், மற்ற எந்தத் துர்க்குணமும் உங்களைவிட்டு நீங்கக்கடவது.", "en": "Let all bitterness, and wrath, and anger, and clamour, and evil speaking, be put away from you, with all malice:"}, {"verse": 32, "start": 249.43, "end": 258.85, "ta": "ஒருவருக்கொருவர் தயவாயும் மனஉருக்கமாயும் இருந்து, கிறிஸ்துவுக்குள் தேவன் உங்களுக்கு மன்னித்ததுபோல, நீங்களும் ஒருவருக்காருவர் மன்னியுங்கள்.", "en": "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you."}]}, "5": {"chapter": 5, "duration": 244.11, "audio_url": "audio_nt/B10_05.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 8.25, "ta": "ஆதலால், நீங்கள் பிரியமான பிள்ளைகளைப்போல தேவனைப் பின்பற்றுகிறவர்களாகி,", "en": "Be ye therefore followers of God, as dear children;"}, {"verse": 2, "start": 8.25, "end": 18.4, "ta": "கிறிஸ்து நமக்காகத் தம்மை தேவனுக்குச் சுகந்த வாசனையான காணிக்கையாகவும் பலியாகவும் ஒப்புக்கொடுத்து நம்மில் அன்புகூர்ந்ததுபோல, நீங்களும் அன்பிலே நடந்துகொள்ளுங்கள்.", "en": "And walk in love, as Christ also hath loved us, and hath given himself for us an offering and a sacrifice to God for a sweetsmelling savour."}, {"verse": 3, "start": 18.4, "end": 28.2, "ta": "மேலும், பரிசுத்தவான்களுக்கு ஏற்றபடி, வேசித்தனமும், மற்றெந்த அசுத்தமும், பொருளாசையுமாகிய இவைகளின் பேர்முதலாய் உங்களுக்குள்ளே சொல்லப்படவுங்கூடாது.", "en": "But fornication, and all uncleanness, or covetousness, let it not be once named among you, as becometh saints;"}, {"verse": 4, "start": 28.2, "end": 34.67, "ta": "அப்படியே வம்பும், புத்தியீனமான பேச்சும், பரியாசமும் தகாதவைகள்; ஸ்தோத்திரஞ்செய்தலே தகும்.", "en": "Neither filthiness, nor foolish talking, nor jesting, which are not convenient: but rather giving of thanks."}, {"verse": 5, "start": 34.67, "end": 45.35, "ta": "விபசாரக்காரனாவது, அசுத்தனாவது, விக்கிரகாராதனைக்காரனாகிய பொருளாசைக்காரனாவது தேவனுடைய ராஜ்யமாகிய கிறிஸ்துவின் ராஜ்யத்திலே சுதந்தரமடைவதில்லையென்று அறிந்திருக்கிறீர்களே.", "en": "For this ye know, that no whoremonger, nor unclean person, nor covetous man, who is an idolater, hath any inheritance in the kingdom of Christ and of God."}, {"verse": 6, "start": 45.35, "end": 55.62, "ta": "இப்படிப்பட்டவைகளினிமித்தமாகக் கீழ்ப்படியாமையின் பிள்ளைகள்மேல் தேவகோபாக்கினை வருவதால், ஒருவனும் உங்களை வீண்வார்த்தைகளினாலே மோசம்போக்காதபடிக்கு எச்சரிக்கையாயிருங்கள்;", "en": "Let no man deceive you with vain words: for because of these things cometh the wrath of God upon the children of disobedience."}, {"verse": 7, "start": 55.62, "end": 58.29, "ta": "அவர்களுக்குப் பங்காளிகளாகாதிருங்கள்.", "en": "Be not ye therefore partakers with them."}, {"verse": 8, "start": 58.29, "end": 67.73, "ta": "முற்காலத்தில் நீங்கள் அந்தகாரமாயிருந்தீர்கள், இப்பொழுதோ கர்த்தருக்குள் வெளிச்சமாயிருக்கிறீர்கள்; வெளிச்சத்தின் பிள்ளைகளாய் நடந்துகொள்ளுங்கள்.", "en": "For ye were sometimes darkness, but now are ye light in the Lord: walk as children of light:"}, {"verse": 9, "start": 67.73, "end": 72.3, "ta": "ஆவியின் கனி, சகல நற்குணத்திலும் நீதியிலும் உண்மையிலும் விளங்கும்.", "en": "(For the fruit of the Spirit is in all goodness and righteousness and truth;)"}, {"verse": 10, "start": 72.3, "end": 76.7, "ta": "கர்த்தருக்குப் பிரியமானது இன்னதென்று நீங்கள் சோதித்துப்பாருங்கள்.", "en": "Proving what is acceptable unto the Lord."}, {"verse": 11, "start": 76.7, "end": 81.68, "ta": "கனியற்ற அந்தகாரக் கிரியைகளுக்கு உடன்படாமல், அவைகளைக் கடிந்துகொள்ளுங்கள்.", "en": "And have no fellowship with the unfruitful works of darkness, but rather reprove them ."}, {"verse": 12, "start": 81.68, "end": 87.26, "ta": "அவர்களால் ஒளிப்பிடத்தில் செய்யப்படும் கிரியைகளைச் சொல்லுகிறதும் அவலட்சணமாயிருக்கிறதே.", "en": "For it is a shame even to speak of those things which are done of them in secret."}, {"verse": 13, "start": 87.26, "end": 94.92, "ta": "அவைகளெல்லாம் கடிந்துகொள்ளப்பட்டு வெளிச்சத்தினால் வெளியரங்கமாகும்; வெளியரங்கமாக்குகிறதெல்லாம் வெளிச்சமாயிருக்கிறது.", "en": "But all things that are reproved are made manifest by the light: for whatsoever doth make manifest is light."}, {"verse": 14, "start": 94.92, "end": 103.53, "ta": "ஆதலால், தூங்குகிற நீ விழித்து, மரித்தோரை விட்டு எழுந்திரு, அப்பொழுது கிறிஸ்து உன்னைப் பிரகாசிப்பிப்பாரென்று சொல்லியிருக்கிறார்.", "en": "Wherefore he saith, Awake thou that sleepest, and arise from the dead, and Christ shall give thee light."}, {"verse": 15, "start": 103.53, "end": 110.06, "ta": "ஆனபடியினாலே, நீங்கள் ஞானமற்றவர்களைப்போல நடவாமல், ஞானமுள்ளவர்களைப்போலக் கவனமாய் நடந்துகொள்ளப்பார்த்து,", "en": "See then that ye walk circumspectly, not as fools, but as wise,"}, {"verse": 16, "start": 110.06, "end": 114.51, "ta": "நாட்கள் பொல்லாதவைகளானதால் காலத்தைப் பிரயோஜனப்படுத்திக்கொள்ளுங்கள்.", "en": "Redeeming the time, because the days are evil."}, {"verse": 17, "start": 114.51, "end": 120.74, "ta": "ஆகையால், நீங்கள் மதியற்றவர்களாயிராமல், கர்த்தருடைய சித்தம் இன்னதென்று உணர்ந்துகொள்ளுங்கள்.", "en": "Wherefore be ye not unwise, but understanding what the will of the Lord is ."}, {"verse": 18, "start": 120.74, "end": 125.31, "ta": "துன்மார்க்கத்திற்கு ஏதுவான மதுபான வெறிகொள்ளாமல், ஆவியினால் நிறைந்து;", "en": "And be not drunk with wine, wherein is excess; but be filled with the Spirit;"}, {"verse": 19, "start": 125.31, "end": 134.51, "ta": "சங்கீதங்களினாலும் கீர்த்தனைகளினாலும் ஞானப்பாட்டுகளினாலும் ஒருவருக்கொருவர் புத்திசொல்லிக்கொண்டு, உங்கள் இருதயத்தில் கர்த்தரைப் பாடிக் கீர்த்தனம்பண்ணி,", "en": "Speaking to yourselves in psalms and hymns and spiritual songs, singing and making melody in your heart to the Lord;"}, {"verse": 20, "start": 134.51, "end": 141.46, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் நாமத்தினாலே எப்பொழுதும் எல்லாவற்றிற்காகவும் பிதாவாகிய தேவனை ஸ்தோத்திரித்து,", "en": "Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;"}, {"verse": 21, "start": 141.46, "end": 145.08, "ta": "தெய்வ பயத்தோடே ஒருவருக்கொருவர் கீழ்ப்படிந்திருங்கள்.", "en": "Submitting yourselves one to another in the fear of God."}, {"verse": 22, "start": 145.08, "end": 151.31, "ta": "மனைவிகளே, கர்த்தருக்குக் கீழ்ப்படிகிறதுபோல, உங்கள் சொந்தப் புருஷருக்குங் கீழ்ப்படியுங்கள்.", "en": "Wives, submit yourselves unto your own husbands, as unto the Lord."}, {"verse": 23, "start": 151.31, "end": 159.62, "ta": "கிறிஸ்து சபைக்குத் தலையாயிருக்கிறதுபோல, புருஷனும் மனைவிக்குத் தலையாயிருக்கிறான்; அவரே சரீரத்திற்கும் இரட்சகராயிருக்கிறார்.", "en": "For the husband is the head of the wife, even as Christ is the head of the church: and he is the saviour of the body."}, {"verse": 24, "start": 159.62, "end": 168.94, "ta": "ஆகையால், சபையானது கிறிஸ்துவுக்குக் கீழ்ப்படிகிறதுபோல மனைவிகளும் தங்கள் சொந்தப் புருஷர்களுக்கு எந்தக் காரியத்திலேயும் கீழ்ப்படிந்திருக்க வேண்டும்.", "en": "Therefore as the church is subject unto Christ, so let the wives be to their own husbands in every thing."}, {"verse": 25, "start": 168.94, "end": 175.0, "ta": "புருஷர்களே, உங்கள் மனைவிகளில் அன்புகூருங்கள்; அப்படியே கிறிஸ்துவும் சபையில் அன்புகூர்ந்து,", "en": "Husbands, love your wives, even as Christ also loved the church, and gave himself for it;"}, {"verse": 26, "start": 175.0, "end": 180.82, "ta": "தாம் அதைத் திருவசனத்தைக்கொண்டு தண்ணீர் முழுக்கினால் சுத்திகரித்து, பரிசுத்தமாக்குகிறதற்கும்,", "en": "That he might sanctify and cleanse it with the washing of water by the word,"}, {"verse": 27, "start": 180.82, "end": 190.85, "ta": "கறைதிரை முதலானவைகள் ஒன்றும் இல்லாமல் பரிசுத்தமும் பிழையற்றதுமான மகிமையுள்ள சபையாக அதைத் தமக்குமுன் நிறுத்திக்கொள்வதற்கும் தம்மைத்தாமே அதற்காக ஒப்புக்கொடுத்தார்.", "en": "That he might present it to himself a glorious church, not having spot, or wrinkle, or any such thing; but that it should be holy and without blemish."}, {"verse": 28, "start": 190.85, "end": 201.89, "ta": "அப்படியே, புருஷர்களும் தங்கள் மனைவிகளைத் தங்கள் சொந்தச் சரீரங்களாகப் பாவித்து, அவர்களில் அன்புகூரவேண்டும்; தன் மனைவியில் அன்புகூருகிறவன் தன்னில்தான் அன்புகூருகிறான்.", "en": "So ought men to love their wives as their own bodies. He that loveth his wife loveth himself."}, {"verse": 29, "start": 201.89, "end": 211.8, "ta": "தன் சொந்த மாம்சத்தைப் பகைத்தவன் ஒருவனுமில்லையே; கர்த்தர் சபையைப் போஷித்துக்காப்பாற்றுகிறது போல ஒவ்வொருவனும் தன் மாம்சத்தைப் போஷித்துக் காப்பாற்றுகிறான்.", "en": "For no man ever yet hated his own flesh; but nourisheth and cherisheth it, even as the Lord the church:"}, {"verse": 30, "start": 211.8, "end": 219.16, "ta": "நாம் அவருடைய சரீரத்தின் அவயவங்களாயும், அவருடைய மாம்சத்திற்கும் அவருடைய எலும்புக்கும் உரியவர்களாயும் இருக்கிறோம்.", "en": "For we are members of his body, of his flesh, and of his bones."}, {"verse": 31, "start": 219.16, "end": 226.88, "ta": "இதினிமித்தம் மனுஷன் தன் தகப்பனையும் தன் தாயையும் விட்டு, தன் மனைவியுடன் இசைந்து, இருவரும் ஒரே மாம்சமாயிருப்பார்கள்.", "en": "For this cause shall a man leave his father and mother, and shall be joined unto his wife, and they two shall be one flesh."}, {"verse": 32, "start": 226.88, "end": 232.52, "ta": "இந்த இரகசியம் பெரியது; நான் கிறிஸ்துவைப்பற்றியும் சபையைப்பற்றியும் சொல்லுகிறேன்.", "en": "This is a great mystery: but I speak concerning Christ and the church."}, {"verse": 33, "start": 232.52, "end": 242.61, "ta": "எப்படியும், உங்களிலும் அவனவன் தன்னிடத்தில் அன்புகூருவதுபோல, தன் மனைவியினிடத்திலும் அன்புகூரக்கடவன்; மனைவியும் புருஷனிடத்தில் பயபக்தியாயிருக்கக்கடவள்.", "en": "Nevertheless let every one of you in particular so love his wife even as himself; and the wife see that she reverence her husband."}]}, "6": {"chapter": 6, "duration": 212.94, "audio_url": "audio_nt/B10_06.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 3.8, "end": 9.43, "ta": "பிள்ளைகளே, உங்கள் பெற்றாருக்குக் கர்த்தருக்குள் கீழ்ப்படியுங்கள், இது நியாயம்.", "en": "Children, obey your parents in the Lord: for this is right."}, {"verse": 2, "start": 9.43, "end": 14.22, "ta": "உனக்கு நன்மை உண்டாயிருப்பதற்கும், பூமியிலே வாழ்நாள் நீடித்திருப்பதற்கும்,", "en": "Honour thy father and mother; (which is the first commandment with promise;)"}, {"verse": 3, "start": 14.22, "end": 20.64, "ta": "உன் தகப்பனையும் உன் தாயையும் கனம்பண்ணுவாயாக என்பதே வாக்குத்தத்தமுள்ள முதலாங் கற்பனையாயிருக்கிறது.", "en": "That it may be well with thee, and thou mayest live long on the earth."}, {"verse": 4, "start": 20.64, "end": 28.88, "ta": "பிதாக்களே, நீங்களும் உங்கள் பிள்ளைகளைக் கோபப்படுத்தாமல், கர்த்தருக்கேற்ற சிட்சையிலும் போதனையிலும் அவர்களை வளர்ப்பீர்களாக.", "en": "And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord."}, {"verse": 5, "start": 28.88, "end": 39.61, "ta": "வேலைக்காரரே, நீங்கள் கிறிஸ்துவுக்குக் கீழ்ப்படிகிறதுபோல, சரீரத்தின்படி உங்கள் எஜமான்களாயிருக்கிறவர்களுக்கும் பயத்தோடும் நடுக்கத்தோடும் கபடற்ற மனதோடும் கீழ்ப்படிந்து;", "en": "Servants, be obedient to them that are your masters according to the flesh, with fear and trembling, in singleness of your heart, as unto Christ;"}, {"verse": 6, "start": 39.61, "end": 49.85, "ta": "மனுஷருக்குப் பிரியமாயிருக்க விரும்புகிறவர்களாகப் பார்வைக்கு ஊழியஞ்செய்யாமல், கிறிஸ்துவின் ஊழியக்காரராக, மனப்பூர்வமாய் தேவனுடைய சித்தத்தின்படி செய்யுங்கள்.", "en": "Not with eyeservice, as menpleasers; but as the servants of Christ, doing the will of God from the heart;"}, {"verse": 7, "start": 49.85, "end": 57.24, "ta": "அடிமையானவனானாலும், சுயாதீனமுள்ளவனானாலும், அவனவன் செய்கிற நன்மையின்படியே கர்த்தரிடத்தில் பலனை அடைவானென்று அறிந்து,", "en": "With good will doing service, as to the Lord, and not to men:"}, {"verse": 8, "start": 57.24, "end": 62.63, "ta": "மனுஷருக்கென்று ஊழியஞ்செய்யாமல், கர்த்தருக்கென்றே நல்மனதோடே ஊழியஞ்செய்யுங்கள்.", "en": "Knowing that whatsoever good thing any man doeth, the same shall he receive of the Lord, whether he be bond or free."}, {"verse": 9, "start": 62.63, "end": 77.23, "ta": "எஜமான்களே, அப்படியே நீங்களும், வேலைக்காரருக்குச் செய்யவேண்டியவைகளைச் செய்து, அவர்களுக்கும் உங்களுக்கும் எஜமானானவர் பரலோகத்தில் இருக்கிறாரென்றும், அவரிடத்தில் பட்சபாதமில்லையென்றும் அறிந்து, கடுஞ்சொல்லை விட்டுவிடுங்கள்.", "en": "And, ye masters, do the same things unto them, forbearing threatening: knowing that your Master also is in heaven; neither is there respect of persons with him."}, {"verse": 10, "start": 77.23, "end": 83.17, "ta": "கடைசியாக, என் சகோதரரே, கர்த்தரிலும் அவருடைய சத்துவத்தின் வல்லமையிலும் பலப்படுங்கள்.", "en": "Finally, my brethren, be strong in the Lord, and in the power of his might."}, {"verse": 11, "start": 83.17, "end": 91.59, "ta": "நீங்கள் பிசாசின் தந்திரங்களோடு எதிர்த்துநிற்கத் திராணியுள்ளவர்களாகும்படி, தேவனுடைய சர்வாயுதவர்க்கத்தையும் தரித்துக்கொள்ளுங்கள்.", "en": "Put on the whole armour of God, that ye may be able to stand against the wiles of the devil."}, {"verse": 12, "start": 91.59, "end": 104.68, "ta": "ஏனெனில், மாம்சத்தோடும் இரத்தத்தோடுமல்ல, துரைத்தனங்களோடும், அதிகாரங்களோடும், இப்பிரபஞ்சத்தின் அந்தகார லோகாதிபதிகளோடும், வானமண்டலங்களிலுள்ள பொல்லாத ஆவிகளின் சேனைகளோடும் நமக்குப் போராட்டம் உண்டு.", "en": "For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places ."}, {"verse": 13, "start": 104.68, "end": 116.56, "ta": "ஆகையால், தீங்குநாளிலே அவைகளை நீங்கள் எதிர்க்கவும், சகலத்தையும் செய்துமுடித்தவர்களாய் நிற்கவும் திராணியுள்ளவர்களாகும்படிக்கு, தேவனுடைய சர்வாயுதவர்க்கத்தையும் எடுத்துக்கொள்ளுங்கள்.", "en": "Wherefore take unto you the whole armour of God, that ye may be able to withstand in the evil day, and having done all, to stand."}, {"verse": 14, "start": 116.56, "end": 123.16, "ta": "சத்தியம் என்னும் கச்சையை உங்கள் அரையில் கட்டினவர்களாயும் நீதியென்னும் மார்க்கவசத்தைத் தரித்தவர்களாயும்;", "en": "Stand therefore, having your loins girt about with truth, and having on the breastplate of righteousness;"}, {"verse": 15, "start": 123.16, "end": 128.74, "ta": "சமாதானத்தின் சுவிசேஷத்திற்குரிய ஆயத்தம் என்னும் பாதரட்சையைக் கால்களிலே தொடுத்தவர்களாயும்,", "en": "And your feet shod with the preparation of the gospel of peace;"}, {"verse": 16, "start": 128.74, "end": 139.16, "ta": "பொல்லாங்கன் எய்யும் அக்கினியாஸ்திரங்களையெல்லாம் அவித்துப்போடத்தக்கதாய், எல்லாவற்றிற்கும் மேலாக விசுவாசமென்னும் கேடகத்தைப் பிடித்துக்கொண்டவர்களாயும் நில்லுங்கள்.", "en": "Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked."}, {"verse": 17, "start": 139.16, "end": 145.28, "ta": "இரட்சணியமென்னும் தலைச்சீராவையும், தேவவசனமாகிய ஆவியின் பட்டயத்தையும் எடுத்துக்கொள்ளுங்கள்.", "en": "And take the helmet of salvation, and the sword of the Spirit, which is the word of God:"}, {"verse": 18, "start": 145.28, "end": 157.64, "ta": "எந்தச் சமயத்திலும் சகலவிதமான வேண்டுதலோடும் விண்ணப்பத்தோடும் ஆவியினாலே ஜெபம்பண்ணி, அதன்பொருட்டு மிகுந்த மனஉறுதியோடும் சகல பரிசுத்தவான்களுக்காகவும் பண்ணும் வேண்டுதலோடும் விழித்துக்கொண்டிருங்கள்.", "en": "Praying always with all prayer and supplication in the Spirit, and watching thereunto with all perseverance and supplication for all saints;"}, {"verse": 19, "start": 157.64, "end": 165.21, "ta": "சுவிசேஷத்திற்காகச் சங்கிலியால் கட்டப்பட்டிருக்கிற ஸ்தானாபதியாகிய நான் அதைப்பற்றிப் பேசவேண்டியபடி தைரியமாய்ப் பேசத்தக்கதாக,", "en": "And for me, that utterance may be given unto me, that I may open my mouth boldly, to make known the mystery of the gospel,"}, {"verse": 20, "start": 165.21, "end": 174.18, "ta": "நான் தைரியமாய் என் வாயைத்திறந்து சுவிசேஷத்தின் இரகசியத்தை அறிவிக்கிறதற்கு வாக்கு எனக்கு கொடுக்கப்படும்படி எனக்காகவும் விண்ணப்பம்பண்ணுங்கள்.", "en": "For which I am an ambassador in bonds: that therein I may speak boldly, as I ought to speak."}, {"verse": 21, "start": 174.18, "end": 188.05, "ta": "அன்றியும், எனக்கடுத்த காரியங்களும், என் சுகசெய்திகளும் உங்களுக்குத் தெரியவரும்படிக்கு, அவைகளையெல்லாம் நமக்குப் பிரியமான சகோதரனும் கர்த்தருக்குள் உண்மையுள்ள ஊழியக்காரனுமாயிருக்கிற தீகிக்கு உங்களுக்கு அறிவிப்பான்.", "en": "But that ye also may know my affairs, and how I do, Tychicus, a beloved brother and faithful minister in the Lord, shall make known to you all things:"}, {"verse": 22, "start": 188.05, "end": 195.69, "ta": "நீங்கள் எங்கள் செய்திகளை அறியவும், அவன் உங்கள் இருதயங்களுக்கு ஆறுதல் செய்யவும், அவனை உங்களிடத்தில் அனுப்பினேன்.", "en": "Whom I have sent unto you for the same purpose, that ye might know our affairs, and that he might comfort your hearts."}, {"verse": 23, "start": 195.69, "end": 203.38, "ta": "பிதாவாகிய தேவனாலும் கர்த்தராகிய இயேசுகிறிஸ்துவினாலும், சகோதரருக்குச் சமாதானமும் விசேஷத்தோடுகூடிய அன்பும் உண்டாவதாக.", "en": "Peace be to the brethren, and love with faith, from God the Father and the Lord Jesus Christ."}, {"verse": 24, "start": 203.38, "end": 211.44, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினிடத்தில் அழியாத அன்புடனே அன்புகூருகிற யாவரோடும் கிருபை உண்டாயிருப்பதாக. ஆமென்.", "en": "Grace be with all them that love our Lord Jesus Christ in sincerity. Amen."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['49'] = {"id": 49, "testament": "NT", "code": "EPH", "name_en": "Ephesians", "name_ta": "எபேசியர்", "category": "Pauline Epistles", "category_ta": "பவுலின் நிருபங்கள்", "total_chapters": 6, "chapters": {"1": {"chapter": 1, "duration": 220.93, "audio_url": "audio_nt/B10_01.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 4.8, "end": 14.89, "ta": "தேவனுடைய சித்தத்தினாலே இயேசுகிறிஸ்துவினுடைய அப்போஸ்தலனாகிய பவுல், எபேசுவிலே கிறிஸ்து இயேசுவுக்குள் விசுவாசிகளாயிருக்கிற பரிசுத்தவான்களுக்கு எழுதுகிறதாவது:", "en": "Paul, an apostle of Jesus Christ by the will of God, to the saints which are at Ephesus, and to the faithful in Christ Jesus:"}, {"verse": 2, "start": 14.89, "end": 22.92, "ta": "நம்முடைய பிதாவாகிய தேவனாலும், கர்த்தராகிய இயேசுகிறிஸ்துவினாலும், உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக.", "en": "Grace be to you, and peace, from God our Father, and from the Lord Jesus Christ."}, {"verse": 3, "start": 22.92, "end": 34.81, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் பிதாவாகிய தேவனுக்கு ஸ்தோத்திரம்; அவர் கிறிஸ்துவுக்குள் உன்னதங்களிலே ஆவிக்குரிய சகல ஆசீர்வாதத்தினாலும் நம்மை ஆசீர்வதித்திருக்கிறார்.", "en": "Blessed be the God and Father of our Lord Jesus Christ, who hath blessed us with all spiritual blessings in heavenly places in Christ:"}, {"verse": 4, "start": 34.81, "end": 45.35, "ta": "தமக்குமுன்பாக நாம் அன்பில் பரிசுத்தமுள்ளவர்களும் குற்றமில்லாதவர்களுமாயிருப்பதற்கு, அவர் உலகத்தோற்றத்துக்கு முன்னே கிறிஸ்துவுக்குள் நம்மைத் தெரிந்துகொண்டபடியே,", "en": "According as he hath chosen us in him before the foundation of the world, that we should be holy and without blame before him in love:"}, {"verse": 5, "start": 45.35, "end": 51.13, "ta": "பிரியமானவருக்குள் தாம் நமக்குத் தந்தருளின தம்முடைய கிருபையின் மகிமைக்குப் புகழ்ச்சியாக,", "en": "Having predestinated us unto the adoption of children by Jesus Christ to himself, according to the good pleasure of his will,"}, {"verse": 6, "start": 51.13, "end": 59.68, "ta": "தம்முடைய தயவுள்ள சித்தத்தின்படியே, நம்மை இயேசுகிறிஸ்துமூலமாய்த் தமக்குச் சுவிகாரபுத்திரராகும்படி முன் குறித்திருக்கிறார்.", "en": "To the praise of the glory of his grace, wherein he hath made us accepted in the beloved."}, {"verse": 7, "start": 59.68, "end": 68.1, "ta": "அவருடைய கிருபையின் ஐசுவரியத்தின்படியே, இவருடைய இரத்தத்தினாலே பாவமன்னிப்பாகிய மீட்பு இவருக்குள் நமக்கு உண்டாயிருக்கிறது.", "en": "In whom we have redemption through his blood, the forgiveness of sins, according to the riches of his grace;"}, {"verse": 8, "start": 68.1, "end": 73.88, "ta": "அந்தக் கிருபையை அவர் சகல ஞானத்தோடும் புத்தியோடும் எங்களிடத்தில் பெருகப்பண்ணினார்.", "en": "Wherein he hath abounded toward us in all wisdom and prudence;"}, {"verse": 9, "start": 73.88, "end": 83.84, "ta": "காலங்கள் நிறைவேறும்போது விளங்கும் நியமத்தின்படி பரலோகத்திலிருக்கிறவைகளும் பூலோகத்திலிருக்கிறவைகளுமாகிய சகலமும் கிறிஸ்துவுக்குள்ளே கூட்டப்படவேண்டுமென்று,", "en": "Having made known unto us the mystery of his will, according to his good pleasure which he hath purposed in himself:"}, {"verse": 10, "start": 83.84, "end": 90.07, "ta": "தமக்குள்ளே தீர்மானித்திருந்த தம்முடைய தயவுள்ள சித்தத்தின் இரகசியத்தை எனக்கு அறிவித்தார்.", "en": "That in the dispensation of the fulness of times he might gather together in one all things in Christ, both which are in heaven, and which are on earth; even in him:"}, {"verse": 11, "start": 90.07, "end": 97.14, "ta": "மேலும் கிறிஸ்துவின்மேல் முன்னே நம்பிக்கையாயிருந்த நாங்கள் அவருடைய மகிமைக்குப் புகழ்ச்சியாயிருக்கும்படிக்கு,", "en": "In whom also we have obtained an inheritance, being predestinated according to the purpose of him who worketh all things after the counsel of his own will:"}, {"verse": 12, "start": 97.14, "end": 109.99, "ta": "தமது சித்தத்தின் ஆலோசனைக்குத்தக்கதாக எல்லாவற்றையும் நடப்பிக்கிற அவருடைய தீர்மானத்தின்படியே, நாங்கள் முன்குறிக்கப்பட்டு, கிறிஸ்துவுக்குள் அவருடைய சுதந்தரமாகும்படி தெரிந்துகொள்ளப்பட்டோம்.", "en": "That we should be to the praise of his glory, who first trusted in Christ."}, {"verse": 13, "start": 109.99, "end": 121.43, "ta": "நீங்களும் உங்கள் இரட்சிப்பின் சுவிசேஷமாகிய சத்திய வசனத்தைக் கேட்டு, விசுவாசிகளானபோது, வாக்குத்தத்தம்பண்ணப்பட்ட பரிசுத்த ஆவியால் அவருக்குள் முத்திரைபோடப்பட்டீர்கள்.", "en": "In whom ye also trusted , after that ye heard the word of truth, the gospel of your salvation: in whom also after that ye believed, ye were sealed with that holy Spirit of promise,"}, {"verse": 14, "start": 121.43, "end": 131.07, "ta": "அவருக்குச் சொந்தமானவர்கள் அவருடைய மகிமைக்குப் புகழ்ச்சியாக மீட்கப்படுவார்கள் என்பதற்கு ஆவியானவர் நம்முடைய சுதந்தரத்தின் அச்சாரமாயிருக்கிறார்.", "en": "Which is the earnest of our inheritance until the redemption of the purchased possession, unto the praise of his glory."}, {"verse": 15, "start": 131.07, "end": 140.58, "ta": "ஆனபடியினாலே, கர்த்தராகிய இயேசுவின்மேலுள்ள உங்கள் விசுவாசத்தையும், பரிசுத்தவான்களெல்லார்மேலுள்ள உங்கள் அன்பையுங்குறித்து நான் கேள்விப்பட்டு,", "en": "Wherefore I also, after I heard of your faith in the Lord Jesus, and love unto all the saints,"}, {"verse": 16, "start": 140.58, "end": 145.59, "ta": "இடைவிடாமல் உங்களுக்காக ஸ்தோத்திரம்பண்ணி, என் ஜெபங்களில் உங்களை நினைத்து,", "en": "Cease not to give thanks for you, making mention of you in my prayers;"}, {"verse": 17, "start": 145.59, "end": 157.1, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் தேவனும் மகிமையின் பிதாவுமானவர் தம்மை நீங்கள் அறிந்துகொள்வதற்கான ஞானத்தையும் தெளிவையும் அளிக்கிற ஆவியை உங்களுக்குத் தந்தருளவேண்டுமென்றும்,", "en": "That the God of our Lord Jesus Christ, the Father of glory, may give unto you the spirit of wisdom and revelation in the knowledge of him:"}, {"verse": 18, "start": 157.1, "end": 168.28, "ta": "தாம் நம்மை அழைத்ததினாலே நமக்கு உண்டாயிருக்கிற நம்பிக்கை இன்னதென்றும், பரிசுத்தவான்களிடத்தில் தமக்கு உண்டாயிருக்கிற சுதந்தரத்தினுடைய மகிமையின் ஐசுவரியம் இன்னதென்றும்;", "en": "The eyes of your understanding being enlightened; that ye may know what is the hope of his calling, and what the riches of the glory of his inheritance in the saints,"}, {"verse": 19, "start": 168.28, "end": 190.0, "ta": "தாம் கிறிஸ்துவை மரித்தோரிலிருந்து எழுப்பி, அவரிடத்தில் நடப்பித்த தமது பலத்த சத்துவத்தின் வல்லமைப்படியே விசுவாசிக்கிறவர்களாகிய நம்மிடத்திலே காண்பிக்கும் தம்முடைய வல்லமையின் மகா மேன்மையான மகத்துவம் இன்னதென்றும், நீங்கள் அறியும்படிக்கு, அவர் உங்களுக்குப் பிரகாசமுள்ள மனக்கண்களைக் கொடுக்கவேண்டுமென்றும் வேண்டிக்கொள்ளுகிறேன்.", "en": "And what is the exceeding greatness of his power to us-ward who believe, according to the working of his mighty power,"}, {"verse": 20, "start": 190.0, "end": 203.17, "ta": "எல்லாத் துரைத்தனத்துக்கும், அதிகாரத்துக்கும், வல்லமைக்கும், கர்த்தத்துவத்துக்கும், இம்மையில்மாத்திரமல்ல மறுமையிலும் பேர்பெற்றிருக்கும் எல்லா நாமத்துக்கும் மேலாய் அவர் உயர்ந்திருக்கத்தக்கதாக,", "en": "Which he wrought in Christ, when he raised him from the dead, and set him at his own right hand in the heavenly places ,"}, {"verse": 21, "start": 203.17, "end": 207.41, "ta": "அவரை உன்னதங்களில் தம்முடைய வலதுபாரிசத்தில் உட்காரும்படி செய்து,", "en": "Far above all principality, and power, and might, and dominion, and every name that is named, not only in this world, but also in that which is to come:"}, {"verse": 22, "start": 207.41, "end": 210.95, "ta": "எல்லாவற்றையும் அவருடைய பாதங்களுக்குக் கீழ்ப்படுத்தி,", "en": "And hath put all things under his feet, and gave him to be the head over all things to the church,"}, {"verse": 23, "start": 210.95, "end": 219.43, "ta": "எல்லாவற்றையும் எல்லாவற்றாலும் நிரப்புகிறவருடைய நிறைவாகிய சரீரமான சபைக்கு அவரை எல்லாவற்றிற்கும் மேலான தலையாகத் தந்தருளினார்.", "en": "Which is his body, the fulness of him that filleth all in all."}]}, "2": {"chapter": 2, "duration": 202.46, "audio_url": "audio_nt/B10_02.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 9.43, "ta": "அக்கிரமங்களினாலும் பாவங்களினாலும் மரித்தவர்களாயிருந்த உங்களை உயிர்ப்பித்தார்.", "en": "And you hath he quickened , who were dead in trespasses and sins;"}, {"verse": 2, "start": 9.43, "end": 22.91, "ta": "அவைகளில் நீங்கள் முற்காலத்திலே இவ்வுலக வழக்கத்திற்கேற்றபடியாகவும், கீழ்ப்படியாமையின் பிள்ளைகளிடத்தில் இப்பொழுது கிரியைசெய்கிற ஆகாயத்து அதிகாரப் பிரபுவாகிய ஆவிக்கேற்றபடியாகவும் நடந்துகொண்டீர்கள்.", "en": "Wherein in time past ye walked according to the course of this world, according to the prince of the power of the air, the spirit that now worketh in the children of disobedience:"}, {"verse": 3, "start": 22.91, "end": 36.33, "ta": "அவர்களுக்குள்ளே நாமெல்லாரும் முற்காலத்திலே நமது மாம்ச இச்சையின்டியே நடந்து, நமது மாம்சமும் மனசும் விரும்பினவைகளைச் செய்து, சுபாவத்தினாலே மற்றவர்களைப்போலக் கோபாக்கினையின் பிள்ளைகளாயிருந்தோம்.", "en": "Among whom also we all had our conversation in times past in the lusts of our flesh, fulfilling the desires of the flesh and of the mind; and were by nature the children of wrath, even as others."}, {"verse": 4, "start": 36.33, "end": 42.03, "ta": "தேவனோ இரக்கத்தில் ஐசுவரியமுள்ளவராய் நம்மில் அன்புகூர்ந்த தம்முடைய மிகுந்த அன்பினாலே,", "en": "But God, who is rich in mercy, for his great love wherewith he loved us,"}, {"verse": 5, "start": 42.03, "end": 50.34, "ta": "அக்கிரமங்களில் மரித்தவர்களாயிருந்த நம்மைக் கிறிஸ்துவுடனேகூட உயிர்ப்பித்தார்; கிருபையினாலே இரட்சிக்கப்பட்டீர்கள்.", "en": "Even when we were dead in sins, hath quickened us together with Christ, (by grace ye are saved;)"}, {"verse": 6, "start": 50.34, "end": 59.83, "ta": "கிறிஸ்து இயேசுவுக்குள் அவர் நம்மிடத்தில் வைத்த தயவினாலே, தம்முடைய கிருபையின் மகா மேன்மையான ஐசுவரியத்தை வருங்காலங்களில் விளங்கச்செய்வதற்காக,", "en": "And hath raised us up together, and made us sit together in heavenly places in Christ Jesus:"}, {"verse": 7, "start": 59.83, "end": 66.57, "ta": "கிறிஸ்து இயேசுவுக்குள் நம்மை அவரோடேகூட எழுப்பி, உன்னதங்களிலே அவரோடேகூட உட்காரவும் செய்தார்.", "en": "That in the ages to come he might shew the exceeding riches of his grace in his kindness toward us through Christ Jesus."}, {"verse": 8, "start": 66.57, "end": 73.97, "ta": "கிருபையினாலே விசுவாசத்தைக்கொண்டு இரட்சிக்கப்பட்டீர்கள்; இது உங்களால் உண்டானதல்ல, இது தேவனுடைய ஈவு;", "en": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"}, {"verse": 9, "start": 73.97, "end": 78.36, "ta": "ஒருவரும் பெருமைபாராட்டாதபடிக்கு இது கிரியைகளினால் உண்டானதல்ல;", "en": "Not of works, lest any man should boast."}, {"verse": 10, "start": 78.36, "end": 92.04, "ta": "ஏனெனில், நற்கிரியைகளைச் செய்கிறதற்கு நாம் கிறிஸ்து இயேசுவுக்குள் சிருஷ்டிக்கப்பட்டு, தேவனுடைய செய்கையாயிருக்கிறோம்; அவைகளில் நாம் நடக்கும்படி அவர் முன்னதாக அவைகளை ஆயத்தம்பண்ணியிருக்கிறார்.", "en": "For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them."}, {"verse": 11, "start": 92.04, "end": 102.71, "ta": "ஆனபடியினால் முன்னே மாம்சத்தின்படி புறஜாதியாராயிருந்து, மாம்சத்தில் கையினாலே செய்யப்படுகிற விருத்தசேதனமுடையவர்களால் விருத்தசேதனமில்லாதவர்களென்னப்பட்ட நீங்கள்,", "en": "Wherefore remember, that ye being in time past Gentiles in the flesh, who are called Uncircumcision by that which is called the Circumcision in the flesh made by hands;"}, {"verse": 12, "start": 102.71, "end": 119.66, "ta": "அக்காலத்திலே இயேசுகிறிஸ்துவைச் சேராதவர்களும், இஸ்ரவேலுடைய காணியாட்சிக்குப் புறம்பானவர்களும், வாக்குத்தத்தத்தின் உடன்படிக்கைகளுக்கு அந்நியரும், நம்பிக்கையில்லாதவர்களும், இவ்வுலகத்தில் தேவனற்றவர்களுமாயிருந்தீர்களென்று நினைத்துக்கொள்ளுங்கள்.", "en": "That at that time ye were without Christ, being aliens from the commonwealth of Israel, and strangers from the covenants of promise, having no hope, and without God in the world:"}, {"verse": 13, "start": 119.66, "end": 126.93, "ta": "முன்னே தூரமாயிருந்த நீங்கள் இப்பொழுது கிறிஸ்து இயேசுவுக்குள் கிறிஸ்துவின் இரத்தத்தினாலே சமீபமானீர்கள்.", "en": "But now in Christ Jesus ye who sometimes were far off are made nigh by the blood of Christ."}, {"verse": 14, "start": 126.93, "end": 135.57, "ta": "எப்படியெனில், அவரே நம்முடைய சமாதானகாரராகி, இருதிறத்தாரையும் ஒன்றாக்கி, பகையாக நின்ற பிரிவினையாகிய நடுச்சுவரைத் தகர்த்து,", "en": "For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us ;"}, {"verse": 15, "start": 135.57, "end": 146.37, "ta": "சட்டதிட்டங்களாகிய நியாயப்பிரமாணத்தைத் தம்முடைய மாம்சத்தினாலே ஒழித்து, இருதிறத்தாரையும் தமக்குள்ளாக ஒரே புதிய மனுஷனாகச் சிருஷ்டித்து, இப்படிச் சமாதானம்பண்ணி,", "en": "Having abolished in his flesh the enmity, even the law of commandments contained in ordinances; for to make in himself of twain one new man, so making peace;"}, {"verse": 16, "start": 146.37, "end": 153.24, "ta": "பகையைச் சிலுவையினால் கொன்று, அதினாலே இருதிறத்தாரையும் ஒரே சரீரமாக தேவனுக்கு ஒப்புரவாக்கினார்.", "en": "And that he might reconcile both unto God in one body by the cross, having slain the enmity thereby:"}, {"verse": 17, "start": 153.24, "end": 161.95, "ta": "அல்லாமலும் அவர் வந்து, தூரமாயிருந்த உங்களுக்கும், சமீபமாயிருந்த அவர்களுக்கும், சமாதானத்தைச் சுவிசேஷமாக அறிவித்தார்.", "en": "And came and preached peace to you which were afar off, and to them that were nigh."}, {"verse": 18, "start": 161.95, "end": 170.0, "ta": "அந்தப்படியே நாம் இருதிறத்தாரும் ஒரே ஆவியினாலே பிதாவினிடத்தில் சேரும் சிலாக்கியத்தை அவர்மூலமாய்ப் பெற்றிருக்கிறோம்.", "en": "For through him we both have access by one Spirit unto the Father."}, {"verse": 19, "start": 170.0, "end": 178.05, "ta": "ஆகையால், நீங்கள் இனி அந்நியரும் பரதேசிகளுமாயிராமல், பரிசுத்தவான்களோடே ஒரே நகரத்தாரும் தேவனுடைய வீட்டாருமாயிருந்து,", "en": "Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;"}, {"verse": 20, "start": 178.05, "end": 188.26, "ta": "அப்போஸ்தலர் தீர்க்கதரிசிகளென்பவர்களுடைய அஸ்திபாரத்தின்மேல் கட்டப்பட்டவர்களுமாயிருக்கிறீர்கள்; அதற்கு இயேசுகிறிஸ்து தாமே மூலைக்கல்லாயிருக்கிறார்;", "en": "And are built upon the foundation of the apostles and prophets, Jesus Christ himself being the chief corner stone ;"}, {"verse": 21, "start": 188.26, "end": 194.94, "ta": "அவர்மேல் மாளிகை முழுவதும் இசைவாய் இணைக்கப்பட்டு, கர்த்தருக்குள் பரிசுத்த ஆலயமாக எழும்புகிறது;", "en": "In whom all the building fitly framed together groweth unto an holy temple in the Lord:"}, {"verse": 22, "start": 194.94, "end": 200.96, "ta": "அவர்மேல் நீங்களும் ஆவியினாலே தேவனுடைய வாசஸ்தலமாகக் கூட்டிக்கட்டப்பட்டுவருகிறீர்கள்.", "en": "In whom ye also are builded together for an habitation of God through the Spirit."}]}, "3": {"chapter": 3, "duration": 196.95, "audio_url": "audio_nt/B10_03.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 12.24, "ta": "இதினித்தம், பவுலாகிய நான் புறஜாதியாராயிருக்கிற உங்கள்பொருட்டுக் கிறிஸ்து இயேசுவினிமித்தம் கட்டுண்டவனாயிருக்கிறேன்.", "en": "For this cause I Paul, the prisoner of Jesus Christ for you Gentiles,"}, {"verse": 2, "start": 12.24, "end": 19.01, "ta": "உங்களுக்காக எனக்கு அளிக்கப்பட்டிருக்கிற தெய்வகிருபைக்குரிய நியமமுமின்னதென்று கேட்டிருப்பீர்களே;", "en": "If ye have heard of the dispensation of the grace of God which is given me to you-ward:"}, {"verse": 3, "start": 19.01, "end": 35.7, "ta": "அதென்னவெனில் புறஜாதிகள் சுவிசேஷத்தினாலே உடன் சுதந்தரருமாய், ஒரே சரீரத்திற்குள்ளானவர்களுமாய், கிறிஸ்துவுக்குள் அவர் பண்ணின வாக்குத்தத்தத்துக்கு உடன்பங்காளிகளுமாயிருக்கிறார்களென்கிற இந்த இரகசியத்தை அவர் எனக்கு வெளிப்படுத்தி அறிவித்தார்.", "en": "How that by revelation he made known unto me the mystery; (as I wrote afore in few words,"}, {"verse": 4, "start": 35.7, "end": 40.12, "ta": "இதைக்குறித்து நான் முன்னமே சுருக்கமாய் எழுதியிருக்கிறேன்.", "en": "Whereby, when ye read, ye may understand my knowledge in the mystery of Christ)"}, {"verse": 5, "start": 40.12, "end": 47.49, "ta": "அதை நீங்கள் வாசிக்கையில் கிறிஸ்துவின் இரகசியத்தைக்குறித்து எனக்கு உண்டாயிருக்கிற அறிவை அறிந்துகொள்ளலாம்;", "en": "Which in other ages was not made known unto the sons of men, as it is now revealed unto his holy apostles and prophets by the Spirit;"}, {"verse": 6, "start": 47.49, "end": 60.16, "ta": "இந்த இரகசியம் இப்பொழுது அவருடைய பரிசுத்த அப்போஸ்தலருக்கும் தீர்க்கதரிசிகளுக்கும் ஆவியானவராலே வெளிப்படுத்தப்பட்டிருக்கிறதுபோல, முற்காலங்களில் மனுபுத்திரருக்கு அறிவிக்கப்படவில்லை.", "en": "That the Gentiles should be fellowheirs, and of the same body, and partakers of his promise in Christ by the gospel:"}, {"verse": 7, "start": 60.16, "end": 68.53, "ta": "தேவனுடைய பலத்த சத்துவத்தால் எனக்கு அளிக்கப்பட்ட வரமாகிய அவருடைய கிருபையினாலே இந்தச் சுவிசேஷத்துக்கு ஊழியக்காரனானேன்.", "en": "Whereof I was made a minister, according to the gift of the grace of God given unto me by the effectual working of his power."}, {"verse": 8, "start": 68.53, "end": 80.59, "ta": "பரிசுத்தவான்களெல்லாரிலும் சிறியவனாகிய நான் கிறிஸ்துவினுடைய அளவற்ற ஐசுவரியத்தைப் புறஜாதிகளிடத்தில் சுவிசேஷமாய் அறிவிக்கிறதற்காக இந்தக் கிருபை எனக்கு அளிக்கப்பட்டிருக்கிறது.", "en": "Unto me, who am less than the least of all saints, is this grace given, that I should preach among the Gentiles the unsearchable riches of Christ;"}, {"verse": 9, "start": 80.59, "end": 86.62, "ta": "தேவன் நம்முடைய கர்த்தராகிய கிறிஸ்து இயேசுவுக்குள் கொண்டிருந்த அநாதி தீர்மானத்தின்படியே,", "en": "And to make all men see what is the fellowship of the mystery, which from the beginning of the world hath been hid in God, who created all things by Jesus Christ:"}, {"verse": 10, "start": 86.62, "end": 95.0, "ta": "உன்னதங்களிலுள்ள துரைத்தனங்களுக்கும் அதிகாரங்களுக்கும் அவருடைய அநந்த ஞானமானது சபையின்மூலமாய் இப்பொழுது தெரியவரும்பொருட்டாக,", "en": "To the intent that now unto the principalities and powers in heavenly places might be known by the church the manifold wisdom of God,"}, {"verse": 11, "start": 95.0, "end": 110.95, "ta": "இயேசுகிறிஸ்துவைக்கொண்டு எல்லாவற்றையும் சிருஷ்டித்த தேவனுக்குள்ளே ஆதிகாலங்கள் முதல் மறைந்திருந்த இரகசியத்தினுடைய ஐக்கியம் இன்னதென்று, எல்லாருக்கும் வெளிப்படையாகக் காண்பிக்கிறதற்கு, இந்தக்கிருபை எனக்கு அளிக்கப்பட்டிருக்கிறது.", "en": "According to the eternal purpose which he purposed in Christ Jesus our Lord:"}, {"verse": 12, "start": 110.95, "end": 120.0, "ta": "அவரைப் பற்றும் விசுவாசத்தால் அவருக்குள் நமக்குத் தைரியமும் திடநம்பிக்கையோடே அவரிடத்தில் சேரும் சிலாக்கியமும் உண்டாயிருக்கிறது.", "en": "In whom we have boldness and access with confidence by the faith of him."}, {"verse": 13, "start": 120.0, "end": 130.78, "ta": "ஆகையால் உங்கள்நிமித்தம் நான் அநுபவிக்கிற உபத்திரவங்களினால் நீங்கள் சோர்ந்துபோகாதிருக்க வேண்டிக்கொள்ளுகிறேன்; அவைகள் உங்களுக்கு மகிமையாயிருக்கிறதே.", "en": "Wherefore I desire that ye faint not at my tribulations for you, which is your glory."}, {"verse": 14, "start": 130.78, "end": 136.75, "ta": "இதினிமித்தம் நான் பரலோகத்திலும் பூலோகத்திலுமுள்ள முழுக்குடும்பத்துக்கும் நாமகாரணராகிய,", "en": "For this cause I bow my knees unto the Father of our Lord Jesus Christ,"}, {"verse": 15, "start": 136.75, "end": 142.38, "ta": "நம்முடைய கர்த்தராயிருக்கிற இயேசுகிறிஸ்துவினுடைய பிதாவை நோக்கி முழங்கால்படியிட்டு,", "en": "Of whom the whole family in heaven and earth is named,"}, {"verse": 16, "start": 142.38, "end": 147.0, "ta": "நீங்கள் அவருடைய ஆவியினாலே உள்ளான மனுஷனில் வல்லமையாய்ப் பலப்படவும்,", "en": "That he would grant you, according to the riches of his glory, to be strengthened with might by his Spirit in the inner man;"}, {"verse": 17, "start": 147.0, "end": 154.77, "ta": "விசுவாசத்தினாலே கிறிஸ்து உங்கள் இருதயங்களில் வாசமாயிருக்கவும், நீங்கள் அன்பிலே வேரூன்றி, நிலைபெற்றவர்களாகி,", "en": "That Christ may dwell in your hearts by faith; that ye, being rooted and grounded in love,"}, {"verse": 18, "start": 154.77, "end": 162.95, "ta": "சகல பரிசுத்தவான்களோடுங்கூடக் கிறிஸ்துவினுடைய அன்பின் அகலமும், நீளமும், ஆழமும், உயரமும் இன்னதென்று உணர்ந்து;", "en": "May be able to comprehend with all saints what is the breadth, and length, and depth, and height;"}, {"verse": 19, "start": 162.95, "end": 177.83, "ta": "அறிவுக்கெட்டாத அந்த அன்பை அறிந்துகொள்ள வல்லவர்களாகவும், தேவனுடைய சகல பரிபூரணத்தாலும் நிறையப்படவும், அவர் தமது மகிமையினுடைய ஐசுவரியத்தின்படியே, உங்களுக்கு அநுக்கிரகம் பண்ணவேண்டுமென்று வேண்டிக்கொள்ளுகிறேன்.", "en": "And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God."}, {"verse": 20, "start": 177.83, "end": 187.68, "ta": "நாம் வேண்டிக்கொள்ளுகிறதற்கும் நினைக்கிறதற்கும் மிகவும் அதிகமாய் நமக்குள்ளே கிரியைசெய்கிற வல்லமையின்படியே, நமக்குச் செய்ய வல்லவராகிய அவருக்கு,", "en": "Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,"}, {"verse": 21, "start": 187.68, "end": 195.45, "ta": "சபையிலே கிறிஸ்து இயேசுவின் மூலமாய்த் தலைமுறை தலைமுறைக்கும் சதாகாலங்களிலும் மகிமை உண்டாவதாக. ஆமென்.", "en": "Unto him be glory in the church by Christ Jesus throughout all ages, world without end. Amen."}]}, "4": {"chapter": 4, "duration": 260.35, "audio_url": "audio_nt/B10_04.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 13.46, "ta": "ஆதலால், கர்த்தர்நிமித்தம் கட்டுண்டவனாகிய நான் உங்களுக்குச் சொல்லுகிற புத்தியென்னவெனில், நீங்கள் அழைக்கப்பட்ட அழைப்புக்குப் பாத்திரவான்களாய் நடந்து,", "en": "I therefore, the prisoner of the Lord, beseech you that ye walk worthy of the vocation wherewith ye are called,"}, {"verse": 2, "start": 13.46, "end": 19.72, "ta": "மிகுந்த மனத்தாழ்மையும் சாந்தமும் நீடிய பொறுமையும் உடையவர்களாய், அன்பினால் ஒருவரையொருவர் தாங்கி,", "en": "With all lowliness and meekness, with longsuffering, forbearing one another in love;"}, {"verse": 3, "start": 19.72, "end": 24.99, "ta": "சமாதானக்கட்டினால் ஆவியின் ஒருமையைக் காத்துக்கொள்வதற்கு ஜாக்கிரதையாயிருங்கள்.", "en": "Endeavouring to keep the unity of the Spirit in the bond of peace."}, {"verse": 4, "start": 24.99, "end": 32.11, "ta": "உங்களுக்கு உண்டான அழைப்பினாலே நீங்கள் ஒரே நம்பிக்கைக்கு அழைக்கப்பட்டதுபோல, ஒரே சரீரமும் ஒரே ஆவியும் உண்டு;", "en": "There is one body, and one Spirit, even as ye are called in one hope of your calling;"}, {"verse": 5, "start": 32.11, "end": 35.77, "ta": "ஒரே கர்த்தரும், ஒரே விசுவாசமும், ஒரே ஞானஸ்நானமும்,", "en": "One Lord, one faith, one baptism,"}, {"verse": 6, "start": 35.77, "end": 44.01, "ta": "எல்லாருக்கும் ஒரே தேவனும் பிதாவும் உண்டு; அவர் எல்லார்மேலும், எல்லாரோடும், உங்கள் எல்லாருக்குள்ளும் இருக்கிறவர்.", "en": "One God and Father of all, who is above all, and through all, and in you all."}, {"verse": 7, "start": 44.01, "end": 50.2, "ta": "கிறிஸ்துவினுடைய ஈவின் அளவுக்குத்தக்கதாக நம்மில் அவனவனுக்குக் கிருபை அளிக்கப்பட்டிருக்கிறது.", "en": "But unto every one of us is given grace according to the measure of the gift of Christ."}, {"verse": 8, "start": 50.2, "end": 58.75, "ta": "ஆதலால், அவர் உன்னதத்திற்கு ஏறி, சிறைப்பட்டவர்களைச் சிறையாக்கி, மனுஷர்களுக்கு வரங்களை அளித்தார் என்று சொல்லியிருக்கிறார்.", "en": "Wherefore he saith, When he ascended up on high, he led captivity captive, and gave gifts unto men."}, {"verse": 9, "start": 58.75, "end": 65.19, "ta": "ஏறினார் என்பதினாலே அவர் அதற்குமுன்னே பூமியின் தாழ்விடங்களில் இறங்கினார் என்று விளங்குகிறதல்லவா?", "en": "(Now that he ascended, what is it but that he also descended first into the lower parts of the earth?"}, {"verse": 10, "start": 65.19, "end": 72.5, "ta": "இறங்கினவரே எல்லாவற்றையும் நிரப்பத்தக்கதாக, எல்லா வானங்களுக்கும் மேலாக உன்னதத்திற்கு ஏறினவருமாயிருக்கிறார்.", "en": "He that descended is the same also that ascended up far above all heavens, that he might fill all things.)"}, {"verse": 11, "start": 72.5, "end": 83.59, "ta": "மேலும் நாம் அனைவரும் தேவனுடைய குமாரனைப் பற்றும் விசுவாசத்திலும் அறிவிலும் ஒருமைப்பட்டவர்களாகி, கிறிஸ்துவினுடைய நிறைவான வளர்ச்சியின் அளவுக்குத்தக்க பூரண புருஷராகும்வரைக்கும்,", "en": "And he gave some, apostles; and some, prophets; and some, evangelists; and some, pastors and teachers;"}, {"verse": 12, "start": 83.59, "end": 92.51, "ta": "பரிசுத்தவான்கள் சீர்பொருந்தும்பொருட்டு, சுவிசேஷ ஊழியத்தின் வேலைக்காகவும், கிறிஸ்துவின் சரீரமாகிய சபையானது பக்திவிருத்தி அடைவதற்காகவும்,", "en": "For the perfecting of the saints, for the work of the ministry, for the edifying of the body of Christ:"}, {"verse": 13, "start": 92.51, "end": 102.3, "ta": "அவர், சிலரை அப்போஸ்தலராகவும், சிலரைத் தீர்க்கதரிசிகளாகவும், சிலரைச் சுவிசேஷகராகவும், சிலரை மேய்ப்பராகவும், போதகராகவும் ஏற்படுத்தினார்.", "en": "Till we all come in the unity of the faith, and of the knowledge of the Son of God, unto a perfect man, unto the measure of the stature of the fulness of Christ:"}, {"verse": 14, "start": 102.3, "end": 111.9, "ta": "நாம் இனிக் குழந்தைகளாயிராமல், மனுஷருடைய சூதும் வஞ்சிக்கிறதற்கேதுவான தந்திரமுமுள்ள போதகமாய் பலவித காற்றினாலே அலைகளைப்போல அடிபட்டு அலைகிறவர்களாயிராமல்,", "en": "That we henceforth be no more children, tossed to and fro, and carried about with every wind of doctrine, by the sleight of men, and cunning craftiness, whereby they lie in wait to deceive;"}, {"verse": 15, "start": 111.9, "end": 120.58, "ta": "அன்புடன் சத்தியத்தைக் கைகொண்டு தலையாகிய கிறிஸ்துவுக்குள் எல்லாவற்றிலேயும், நாம் வளருகிறவர்களாயிருக்கும்படியாக அப்படிச் செய்தார்.", "en": "But speaking the truth in love, may grow up into him in all things, which is the head, even Christ:"}, {"verse": 16, "start": 120.58, "end": 137.3, "ta": "அவராலே சரீரம் முழுதும், அதற்கு உதவியாயிருக்கிற சகல கணுக்களினாலும் இசைவாய்க் கட்டி இணைக்கப்பட்டு, ஒவ்வொரு அவயவமும் தன்தன் அளவுக்குத்தக்கதாய்க் கிரியைசெய்கிறபடியே, அது அன்பினாலே தனக்கு பக்திவிருத்தி உண்டாக்குகிறதற்கேதுவாகச் சரீரவளர்ச்சியை உண்டாக்குகிறது.", "en": "From whom the whole body fitly joined together and compacted by that which every joint supplieth, according to the effectual working in the measure of every part, maketh increase of the body unto the edifying of itself in love."}, {"verse": 17, "start": 137.3, "end": 148.64, "ta": "ஆதலால், கர்த்தருக்குள் நான் உங்களுக்குச் சாட்சியாகச் சொல்லி எச்சரிக்கிறது என்னவெனில், மற்றப் புறஜாதிகள் தங்கள் வீணான சிந்தையிலே நடக்கிறதுபோல நீங்கள் இனி நடவாமலிருங்கள்.", "en": "This I say therefore, and testify in the Lord, that ye henceforth walk not as other Gentiles walk, in the vanity of their mind,"}, {"verse": 18, "start": 148.64, "end": 157.25, "ta": "அவர்கள் புத்தியில் அந்தகாரப்பட்டு, தங்கள் இருதய கடினத்தினால் தங்களில் இருக்கும் அறியாமையினாலே தேவனுடைய ஜீவனுக்கு அந்நியராயிருந்து;", "en": "Having the understanding darkened, being alienated from the life of God through the ignorance that is in them, because of the blindness of their heart:"}, {"verse": 19, "start": 157.25, "end": 165.8, "ta": "உணர்வில்லாதவர்களாய், சகலவித அசுத்தங்களையும் ஆவலோடே நடப்பிக்கும்படி, தங்களைக் காமவிகாரத்திற்கு ஒப்புக்கொடுத்திருக்கிறார்கள்.", "en": "Who being past feeling have given themselves over unto lasciviousness, to work all uncleanness with greediness."}, {"verse": 20, "start": 165.8, "end": 169.64, "ta": "நீங்களோ இவ்விதமாய்க் கிறிஸ்துவைக் கற்றுக்கொள்ளவில்லை.", "en": "But ye have not so learned Christ;"}, {"verse": 21, "start": 169.64, "end": 176.7, "ta": "இயேசுவினிடத்திலுள்ள சத்தியத்தின்படியே, நீங்கள் அவரிடத்தில் கேட்டறிந்து, அவரால் போதிக்கப்பட்டீர்களே.", "en": "If so be that ye have heard him, and have been taught by him, as the truth is in Jesus:"}, {"verse": 22, "start": 176.7, "end": 183.64, "ta": "அந்தப்படி, முந்தின நடக்கைக்குரிய மோசம்போக்கும் இச்சைகளாலே கெட்டுப்போகிற பழைய மனுஷனை நீங்கள் களைந்துபோட்டு,", "en": "That ye put off concerning the former conversation the old man, which is corrupt according to the deceitful lusts;"}, {"verse": 23, "start": 183.64, "end": 186.49, "ta": "உங்கள் உள்ளத்திலே புதிதான ஆவியுள்ளவர்களாகி,", "en": "And be renewed in the spirit of your mind;"}, {"verse": 24, "start": 186.49, "end": 193.62, "ta": "மெய்யான நீதியிலும் பரிசுத்தத்திலும் தேவனுடைய சாயலாக சிருஷ்டிக்கப்பட்ட புதிய மனுஷனைத் தரித்துக்கொள்ளுங்கள்.", "en": "And that ye put on the new man, which after God is created in righteousness and true holiness."}, {"verse": 25, "start": 193.62, "end": 201.73, "ta": "அன்றியும், நாம் ஒருவருக்கொருவர் அவயவங்களாயிருக்கிறபடியால், பொய்யைக் களைந்து, அவனவன் பிறனுடனே மெய்யைப் பேசக்கடவன்.", "en": "Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another."}, {"verse": 26, "start": 201.73, "end": 208.92, "ta": "நீங்கள் கோபங்கொண்டாலும் பாவஞ்செய்யாதிருங்கள், சூரியன் அஸ்தமிக்கிறதற்கு முன்னாக உங்கள் எரிச்சல் தணியக்கடவது;", "en": "Be ye angry, and sin not: let not the sun go down upon your wrath:"}, {"verse": 27, "start": 208.92, "end": 211.58, "ta": "பிசாசுக்கு இடங்கொடாமலும் இருங்கள்.", "en": "Neither give place to the devil."}, {"verse": 28, "start": 211.58, "end": 221.87, "ta": "திருடுகிறவன் இனித் திருடாமல், குறைச்சலுள்ளவனுக்குக் கொடுக்கத்தக்கதாகத் தனக்கு உண்டாயிருக்கும்படி, தன் கைகளினால் நலமான வேலைசெய்து, பிரயாசப்படக்கடவன்.", "en": "Let him that stole steal no more: but rather let him labour, working with his hands the thing which is good, that he may have to give to him that needeth."}, {"verse": 29, "start": 221.87, "end": 232.89, "ta": "கெட்ட வார்த்தை ஒன்றும் உங்கள் வாயிலிருந்து புறப்படவேண்டாம்; பக்திவிருத்திக்கு ஏதுவான நல்ல வார்த்தை உண்டானால் அதையே கேட்கிறவனுக்குப் பிரயோஜனமுண்டாகும்படி பேசுங்கள்.", "en": "Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers."}, {"verse": 30, "start": 232.89, "end": 240.7, "ta": "அன்றியும், நீங்கள் மீட்கப்படும்நாளுக்கென்று முத்திரையாகப் பெற்ற தேவனுடைய பரிசுத்த ஆவியைத் துக்கப்படுத்தாதிருங்கள்.", "en": "And grieve not the holy Spirit of God, whereby ye are sealed unto the day of redemption."}, {"verse": 31, "start": 240.7, "end": 249.43, "ta": "சகலவிதமான கசப்பும், கோபமும், மூர்க்கமும், கூக்குரலும், தூஷணமும், மற்ற எந்தத் துர்க்குணமும் உங்களைவிட்டு நீங்கக்கடவது.", "en": "Let all bitterness, and wrath, and anger, and clamour, and evil speaking, be put away from you, with all malice:"}, {"verse": 32, "start": 249.43, "end": 258.85, "ta": "ஒருவருக்கொருவர் தயவாயும் மனஉருக்கமாயும் இருந்து, கிறிஸ்துவுக்குள் தேவன் உங்களுக்கு மன்னித்ததுபோல, நீங்களும் ஒருவருக்காருவர் மன்னியுங்கள்.", "en": "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you."}]}, "5": {"chapter": 5, "duration": 244.11, "audio_url": "audio_nt/B10_05.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 8.25, "ta": "ஆதலால், நீங்கள் பிரியமான பிள்ளைகளைப்போல தேவனைப் பின்பற்றுகிறவர்களாகி,", "en": "Be ye therefore followers of God, as dear children;"}, {"verse": 2, "start": 8.25, "end": 18.4, "ta": "கிறிஸ்து நமக்காகத் தம்மை தேவனுக்குச் சுகந்த வாசனையான காணிக்கையாகவும் பலியாகவும் ஒப்புக்கொடுத்து நம்மில் அன்புகூர்ந்ததுபோல, நீங்களும் அன்பிலே நடந்துகொள்ளுங்கள்.", "en": "And walk in love, as Christ also hath loved us, and hath given himself for us an offering and a sacrifice to God for a sweetsmelling savour."}, {"verse": 3, "start": 18.4, "end": 28.2, "ta": "மேலும், பரிசுத்தவான்களுக்கு ஏற்றபடி, வேசித்தனமும், மற்றெந்த அசுத்தமும், பொருளாசையுமாகிய இவைகளின் பேர்முதலாய் உங்களுக்குள்ளே சொல்லப்படவுங்கூடாது.", "en": "But fornication, and all uncleanness, or covetousness, let it not be once named among you, as becometh saints;"}, {"verse": 4, "start": 28.2, "end": 34.67, "ta": "அப்படியே வம்பும், புத்தியீனமான பேச்சும், பரியாசமும் தகாதவைகள்; ஸ்தோத்திரஞ்செய்தலே தகும்.", "en": "Neither filthiness, nor foolish talking, nor jesting, which are not convenient: but rather giving of thanks."}, {"verse": 5, "start": 34.67, "end": 45.35, "ta": "விபசாரக்காரனாவது, அசுத்தனாவது, விக்கிரகாராதனைக்காரனாகிய பொருளாசைக்காரனாவது தேவனுடைய ராஜ்யமாகிய கிறிஸ்துவின் ராஜ்யத்திலே சுதந்தரமடைவதில்லையென்று அறிந்திருக்கிறீர்களே.", "en": "For this ye know, that no whoremonger, nor unclean person, nor covetous man, who is an idolater, hath any inheritance in the kingdom of Christ and of God."}, {"verse": 6, "start": 45.35, "end": 55.62, "ta": "இப்படிப்பட்டவைகளினிமித்தமாகக் கீழ்ப்படியாமையின் பிள்ளைகள்மேல் தேவகோபாக்கினை வருவதால், ஒருவனும் உங்களை வீண்வார்த்தைகளினாலே மோசம்போக்காதபடிக்கு எச்சரிக்கையாயிருங்கள்;", "en": "Let no man deceive you with vain words: for because of these things cometh the wrath of God upon the children of disobedience."}, {"verse": 7, "start": 55.62, "end": 58.29, "ta": "அவர்களுக்குப் பங்காளிகளாகாதிருங்கள்.", "en": "Be not ye therefore partakers with them."}, {"verse": 8, "start": 58.29, "end": 67.73, "ta": "முற்காலத்தில் நீங்கள் அந்தகாரமாயிருந்தீர்கள், இப்பொழுதோ கர்த்தருக்குள் வெளிச்சமாயிருக்கிறீர்கள்; வெளிச்சத்தின் பிள்ளைகளாய் நடந்துகொள்ளுங்கள்.", "en": "For ye were sometimes darkness, but now are ye light in the Lord: walk as children of light:"}, {"verse": 9, "start": 67.73, "end": 72.3, "ta": "ஆவியின் கனி, சகல நற்குணத்திலும் நீதியிலும் உண்மையிலும் விளங்கும்.", "en": "(For the fruit of the Spirit is in all goodness and righteousness and truth;)"}, {"verse": 10, "start": 72.3, "end": 76.7, "ta": "கர்த்தருக்குப் பிரியமானது இன்னதென்று நீங்கள் சோதித்துப்பாருங்கள்.", "en": "Proving what is acceptable unto the Lord."}, {"verse": 11, "start": 76.7, "end": 81.68, "ta": "கனியற்ற அந்தகாரக் கிரியைகளுக்கு உடன்படாமல், அவைகளைக் கடிந்துகொள்ளுங்கள்.", "en": "And have no fellowship with the unfruitful works of darkness, but rather reprove them ."}, {"verse": 12, "start": 81.68, "end": 87.26, "ta": "அவர்களால் ஒளிப்பிடத்தில் செய்யப்படும் கிரியைகளைச் சொல்லுகிறதும் அவலட்சணமாயிருக்கிறதே.", "en": "For it is a shame even to speak of those things which are done of them in secret."}, {"verse": 13, "start": 87.26, "end": 94.92, "ta": "அவைகளெல்லாம் கடிந்துகொள்ளப்பட்டு வெளிச்சத்தினால் வெளியரங்கமாகும்; வெளியரங்கமாக்குகிறதெல்லாம் வெளிச்சமாயிருக்கிறது.", "en": "But all things that are reproved are made manifest by the light: for whatsoever doth make manifest is light."}, {"verse": 14, "start": 94.92, "end": 103.53, "ta": "ஆதலால், தூங்குகிற நீ விழித்து, மரித்தோரை விட்டு எழுந்திரு, அப்பொழுது கிறிஸ்து உன்னைப் பிரகாசிப்பிப்பாரென்று சொல்லியிருக்கிறார்.", "en": "Wherefore he saith, Awake thou that sleepest, and arise from the dead, and Christ shall give thee light."}, {"verse": 15, "start": 103.53, "end": 110.06, "ta": "ஆனபடியினாலே, நீங்கள் ஞானமற்றவர்களைப்போல நடவாமல், ஞானமுள்ளவர்களைப்போலக் கவனமாய் நடந்துகொள்ளப்பார்த்து,", "en": "See then that ye walk circumspectly, not as fools, but as wise,"}, {"verse": 16, "start": 110.06, "end": 114.51, "ta": "நாட்கள் பொல்லாதவைகளானதால் காலத்தைப் பிரயோஜனப்படுத்திக்கொள்ளுங்கள்.", "en": "Redeeming the time, because the days are evil."}, {"verse": 17, "start": 114.51, "end": 120.74, "ta": "ஆகையால், நீங்கள் மதியற்றவர்களாயிராமல், கர்த்தருடைய சித்தம் இன்னதென்று உணர்ந்துகொள்ளுங்கள்.", "en": "Wherefore be ye not unwise, but understanding what the will of the Lord is ."}, {"verse": 18, "start": 120.74, "end": 125.31, "ta": "துன்மார்க்கத்திற்கு ஏதுவான மதுபான வெறிகொள்ளாமல், ஆவியினால் நிறைந்து;", "en": "And be not drunk with wine, wherein is excess; but be filled with the Spirit;"}, {"verse": 19, "start": 125.31, "end": 134.51, "ta": "சங்கீதங்களினாலும் கீர்த்தனைகளினாலும் ஞானப்பாட்டுகளினாலும் ஒருவருக்கொருவர் புத்திசொல்லிக்கொண்டு, உங்கள் இருதயத்தில் கர்த்தரைப் பாடிக் கீர்த்தனம்பண்ணி,", "en": "Speaking to yourselves in psalms and hymns and spiritual songs, singing and making melody in your heart to the Lord;"}, {"verse": 20, "start": 134.51, "end": 141.46, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் நாமத்தினாலே எப்பொழுதும் எல்லாவற்றிற்காகவும் பிதாவாகிய தேவனை ஸ்தோத்திரித்து,", "en": "Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;"}, {"verse": 21, "start": 141.46, "end": 145.08, "ta": "தெய்வ பயத்தோடே ஒருவருக்கொருவர் கீழ்ப்படிந்திருங்கள்.", "en": "Submitting yourselves one to another in the fear of God."}, {"verse": 22, "start": 145.08, "end": 151.31, "ta": "மனைவிகளே, கர்த்தருக்குக் கீழ்ப்படிகிறதுபோல, உங்கள் சொந்தப் புருஷருக்குங் கீழ்ப்படியுங்கள்.", "en": "Wives, submit yourselves unto your own husbands, as unto the Lord."}, {"verse": 23, "start": 151.31, "end": 159.62, "ta": "கிறிஸ்து சபைக்குத் தலையாயிருக்கிறதுபோல, புருஷனும் மனைவிக்குத் தலையாயிருக்கிறான்; அவரே சரீரத்திற்கும் இரட்சகராயிருக்கிறார்.", "en": "For the husband is the head of the wife, even as Christ is the head of the church: and he is the saviour of the body."}, {"verse": 24, "start": 159.62, "end": 168.94, "ta": "ஆகையால், சபையானது கிறிஸ்துவுக்குக் கீழ்ப்படிகிறதுபோல மனைவிகளும் தங்கள் சொந்தப் புருஷர்களுக்கு எந்தக் காரியத்திலேயும் கீழ்ப்படிந்திருக்க வேண்டும்.", "en": "Therefore as the church is subject unto Christ, so let the wives be to their own husbands in every thing."}, {"verse": 25, "start": 168.94, "end": 175.0, "ta": "புருஷர்களே, உங்கள் மனைவிகளில் அன்புகூருங்கள்; அப்படியே கிறிஸ்துவும் சபையில் அன்புகூர்ந்து,", "en": "Husbands, love your wives, even as Christ also loved the church, and gave himself for it;"}, {"verse": 26, "start": 175.0, "end": 180.82, "ta": "தாம் அதைத் திருவசனத்தைக்கொண்டு தண்ணீர் முழுக்கினால் சுத்திகரித்து, பரிசுத்தமாக்குகிறதற்கும்,", "en": "That he might sanctify and cleanse it with the washing of water by the word,"}, {"verse": 27, "start": 180.82, "end": 190.85, "ta": "கறைதிரை முதலானவைகள் ஒன்றும் இல்லாமல் பரிசுத்தமும் பிழையற்றதுமான மகிமையுள்ள சபையாக அதைத் தமக்குமுன் நிறுத்திக்கொள்வதற்கும் தம்மைத்தாமே அதற்காக ஒப்புக்கொடுத்தார்.", "en": "That he might present it to himself a glorious church, not having spot, or wrinkle, or any such thing; but that it should be holy and without blemish."}, {"verse": 28, "start": 190.85, "end": 201.89, "ta": "அப்படியே, புருஷர்களும் தங்கள் மனைவிகளைத் தங்கள் சொந்தச் சரீரங்களாகப் பாவித்து, அவர்களில் அன்புகூரவேண்டும்; தன் மனைவியில் அன்புகூருகிறவன் தன்னில்தான் அன்புகூருகிறான்.", "en": "So ought men to love their wives as their own bodies. He that loveth his wife loveth himself."}, {"verse": 29, "start": 201.89, "end": 211.8, "ta": "தன் சொந்த மாம்சத்தைப் பகைத்தவன் ஒருவனுமில்லையே; கர்த்தர் சபையைப் போஷித்துக்காப்பாற்றுகிறது போல ஒவ்வொருவனும் தன் மாம்சத்தைப் போஷித்துக் காப்பாற்றுகிறான்.", "en": "For no man ever yet hated his own flesh; but nourisheth and cherisheth it, even as the Lord the church:"}, {"verse": 30, "start": 211.8, "end": 219.16, "ta": "நாம் அவருடைய சரீரத்தின் அவயவங்களாயும், அவருடைய மாம்சத்திற்கும் அவருடைய எலும்புக்கும் உரியவர்களாயும் இருக்கிறோம்.", "en": "For we are members of his body, of his flesh, and of his bones."}, {"verse": 31, "start": 219.16, "end": 226.88, "ta": "இதினிமித்தம் மனுஷன் தன் தகப்பனையும் தன் தாயையும் விட்டு, தன் மனைவியுடன் இசைந்து, இருவரும் ஒரே மாம்சமாயிருப்பார்கள்.", "en": "For this cause shall a man leave his father and mother, and shall be joined unto his wife, and they two shall be one flesh."}, {"verse": 32, "start": 226.88, "end": 232.52, "ta": "இந்த இரகசியம் பெரியது; நான் கிறிஸ்துவைப்பற்றியும் சபையைப்பற்றியும் சொல்லுகிறேன்.", "en": "This is a great mystery: but I speak concerning Christ and the church."}, {"verse": 33, "start": 232.52, "end": 242.61, "ta": "எப்படியும், உங்களிலும் அவனவன் தன்னிடத்தில் அன்புகூருவதுபோல, தன் மனைவியினிடத்திலும் அன்புகூரக்கடவன்; மனைவியும் புருஷனிடத்தில் பயபக்தியாயிருக்கக்கடவள்.", "en": "Nevertheless let every one of you in particular so love his wife even as himself; and the wife see that she reverence her husband."}]}, "6": {"chapter": 6, "duration": 212.94, "audio_url": "audio_nt/B10_06.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 3.8, "end": 9.43, "ta": "பிள்ளைகளே, உங்கள் பெற்றாருக்குக் கர்த்தருக்குள் கீழ்ப்படியுங்கள், இது நியாயம்.", "en": "Children, obey your parents in the Lord: for this is right."}, {"verse": 2, "start": 9.43, "end": 14.22, "ta": "உனக்கு நன்மை உண்டாயிருப்பதற்கும், பூமியிலே வாழ்நாள் நீடித்திருப்பதற்கும்,", "en": "Honour thy father and mother; (which is the first commandment with promise;)"}, {"verse": 3, "start": 14.22, "end": 20.64, "ta": "உன் தகப்பனையும் உன் தாயையும் கனம்பண்ணுவாயாக என்பதே வாக்குத்தத்தமுள்ள முதலாங் கற்பனையாயிருக்கிறது.", "en": "That it may be well with thee, and thou mayest live long on the earth."}, {"verse": 4, "start": 20.64, "end": 28.88, "ta": "பிதாக்களே, நீங்களும் உங்கள் பிள்ளைகளைக் கோபப்படுத்தாமல், கர்த்தருக்கேற்ற சிட்சையிலும் போதனையிலும் அவர்களை வளர்ப்பீர்களாக.", "en": "And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord."}, {"verse": 5, "start": 28.88, "end": 39.61, "ta": "வேலைக்காரரே, நீங்கள் கிறிஸ்துவுக்குக் கீழ்ப்படிகிறதுபோல, சரீரத்தின்படி உங்கள் எஜமான்களாயிருக்கிறவர்களுக்கும் பயத்தோடும் நடுக்கத்தோடும் கபடற்ற மனதோடும் கீழ்ப்படிந்து;", "en": "Servants, be obedient to them that are your masters according to the flesh, with fear and trembling, in singleness of your heart, as unto Christ;"}, {"verse": 6, "start": 39.61, "end": 49.85, "ta": "மனுஷருக்குப் பிரியமாயிருக்க விரும்புகிறவர்களாகப் பார்வைக்கு ஊழியஞ்செய்யாமல், கிறிஸ்துவின் ஊழியக்காரராக, மனப்பூர்வமாய் தேவனுடைய சித்தத்தின்படி செய்யுங்கள்.", "en": "Not with eyeservice, as menpleasers; but as the servants of Christ, doing the will of God from the heart;"}, {"verse": 7, "start": 49.85, "end": 57.24, "ta": "அடிமையானவனானாலும், சுயாதீனமுள்ளவனானாலும், அவனவன் செய்கிற நன்மையின்படியே கர்த்தரிடத்தில் பலனை அடைவானென்று அறிந்து,", "en": "With good will doing service, as to the Lord, and not to men:"}, {"verse": 8, "start": 57.24, "end": 62.63, "ta": "மனுஷருக்கென்று ஊழியஞ்செய்யாமல், கர்த்தருக்கென்றே நல்மனதோடே ஊழியஞ்செய்யுங்கள்.", "en": "Knowing that whatsoever good thing any man doeth, the same shall he receive of the Lord, whether he be bond or free."}, {"verse": 9, "start": 62.63, "end": 77.23, "ta": "எஜமான்களே, அப்படியே நீங்களும், வேலைக்காரருக்குச் செய்யவேண்டியவைகளைச் செய்து, அவர்களுக்கும் உங்களுக்கும் எஜமானானவர் பரலோகத்தில் இருக்கிறாரென்றும், அவரிடத்தில் பட்சபாதமில்லையென்றும் அறிந்து, கடுஞ்சொல்லை விட்டுவிடுங்கள்.", "en": "And, ye masters, do the same things unto them, forbearing threatening: knowing that your Master also is in heaven; neither is there respect of persons with him."}, {"verse": 10, "start": 77.23, "end": 83.17, "ta": "கடைசியாக, என் சகோதரரே, கர்த்தரிலும் அவருடைய சத்துவத்தின் வல்லமையிலும் பலப்படுங்கள்.", "en": "Finally, my brethren, be strong in the Lord, and in the power of his might."}, {"verse": 11, "start": 83.17, "end": 91.59, "ta": "நீங்கள் பிசாசின் தந்திரங்களோடு எதிர்த்துநிற்கத் திராணியுள்ளவர்களாகும்படி, தேவனுடைய சர்வாயுதவர்க்கத்தையும் தரித்துக்கொள்ளுங்கள்.", "en": "Put on the whole armour of God, that ye may be able to stand against the wiles of the devil."}, {"verse": 12, "start": 91.59, "end": 104.68, "ta": "ஏனெனில், மாம்சத்தோடும் இரத்தத்தோடுமல்ல, துரைத்தனங்களோடும், அதிகாரங்களோடும், இப்பிரபஞ்சத்தின் அந்தகார லோகாதிபதிகளோடும், வானமண்டலங்களிலுள்ள பொல்லாத ஆவிகளின் சேனைகளோடும் நமக்குப் போராட்டம் உண்டு.", "en": "For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places ."}, {"verse": 13, "start": 104.68, "end": 116.56, "ta": "ஆகையால், தீங்குநாளிலே அவைகளை நீங்கள் எதிர்க்கவும், சகலத்தையும் செய்துமுடித்தவர்களாய் நிற்கவும் திராணியுள்ளவர்களாகும்படிக்கு, தேவனுடைய சர்வாயுதவர்க்கத்தையும் எடுத்துக்கொள்ளுங்கள்.", "en": "Wherefore take unto you the whole armour of God, that ye may be able to withstand in the evil day, and having done all, to stand."}, {"verse": 14, "start": 116.56, "end": 123.16, "ta": "சத்தியம் என்னும் கச்சையை உங்கள் அரையில் கட்டினவர்களாயும் நீதியென்னும் மார்க்கவசத்தைத் தரித்தவர்களாயும்;", "en": "Stand therefore, having your loins girt about with truth, and having on the breastplate of righteousness;"}, {"verse": 15, "start": 123.16, "end": 128.74, "ta": "சமாதானத்தின் சுவிசேஷத்திற்குரிய ஆயத்தம் என்னும் பாதரட்சையைக் கால்களிலே தொடுத்தவர்களாயும்,", "en": "And your feet shod with the preparation of the gospel of peace;"}, {"verse": 16, "start": 128.74, "end": 139.16, "ta": "பொல்லாங்கன் எய்யும் அக்கினியாஸ்திரங்களையெல்லாம் அவித்துப்போடத்தக்கதாய், எல்லாவற்றிற்கும் மேலாக விசுவாசமென்னும் கேடகத்தைப் பிடித்துக்கொண்டவர்களாயும் நில்லுங்கள்.", "en": "Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked."}, {"verse": 17, "start": 139.16, "end": 145.28, "ta": "இரட்சணியமென்னும் தலைச்சீராவையும், தேவவசனமாகிய ஆவியின் பட்டயத்தையும் எடுத்துக்கொள்ளுங்கள்.", "en": "And take the helmet of salvation, and the sword of the Spirit, which is the word of God:"}, {"verse": 18, "start": 145.28, "end": 157.64, "ta": "எந்தச் சமயத்திலும் சகலவிதமான வேண்டுதலோடும் விண்ணப்பத்தோடும் ஆவியினாலே ஜெபம்பண்ணி, அதன்பொருட்டு மிகுந்த மனஉறுதியோடும் சகல பரிசுத்தவான்களுக்காகவும் பண்ணும் வேண்டுதலோடும் விழித்துக்கொண்டிருங்கள்.", "en": "Praying always with all prayer and supplication in the Spirit, and watching thereunto with all perseverance and supplication for all saints;"}, {"verse": 19, "start": 157.64, "end": 165.21, "ta": "சுவிசேஷத்திற்காகச் சங்கிலியால் கட்டப்பட்டிருக்கிற ஸ்தானாபதியாகிய நான் அதைப்பற்றிப் பேசவேண்டியபடி தைரியமாய்ப் பேசத்தக்கதாக,", "en": "And for me, that utterance may be given unto me, that I may open my mouth boldly, to make known the mystery of the gospel,"}, {"verse": 20, "start": 165.21, "end": 174.18, "ta": "நான் தைரியமாய் என் வாயைத்திறந்து சுவிசேஷத்தின் இரகசியத்தை அறிவிக்கிறதற்கு வாக்கு எனக்கு கொடுக்கப்படும்படி எனக்காகவும் விண்ணப்பம்பண்ணுங்கள்.", "en": "For which I am an ambassador in bonds: that therein I may speak boldly, as I ought to speak."}, {"verse": 21, "start": 174.18, "end": 188.05, "ta": "அன்றியும், எனக்கடுத்த காரியங்களும், என் சுகசெய்திகளும் உங்களுக்குத் தெரியவரும்படிக்கு, அவைகளையெல்லாம் நமக்குப் பிரியமான சகோதரனும் கர்த்தருக்குள் உண்மையுள்ள ஊழியக்காரனுமாயிருக்கிற தீகிக்கு உங்களுக்கு அறிவிப்பான்.", "en": "But that ye also may know my affairs, and how I do, Tychicus, a beloved brother and faithful minister in the Lord, shall make known to you all things:"}, {"verse": 22, "start": 188.05, "end": 195.69, "ta": "நீங்கள் எங்கள் செய்திகளை அறியவும், அவன் உங்கள் இருதயங்களுக்கு ஆறுதல் செய்யவும், அவனை உங்களிடத்தில் அனுப்பினேன்.", "en": "Whom I have sent unto you for the same purpose, that ye might know our affairs, and that he might comfort your hearts."}, {"verse": 23, "start": 195.69, "end": 203.38, "ta": "பிதாவாகிய தேவனாலும் கர்த்தராகிய இயேசுகிறிஸ்துவினாலும், சகோதரருக்குச் சமாதானமும் விசேஷத்தோடுகூடிய அன்பும் உண்டாவதாக.", "en": "Peace be to the brethren, and love with faith, from God the Father and the Lord Jesus Christ."}, {"verse": 24, "start": 203.38, "end": 211.44, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினிடத்தில் அழியாத அன்புடனே அன்புகூருகிற யாவரோடும் கிருபை உண்டாயிருப்பதாக. ஆமென்.", "en": "Grace be with all them that love our Lord Jesus Christ in sincerity. Amen."}]}}};
}
